import math

def largest_prime_factor_gt_1000(n):
    # Input validation
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def prime_factors(n, primes):
        factors = []
        for prime in primes:
            if prime > int(math.sqrt(n)):
                break
            while n % prime == 0:
                factors.append(prime)
                n //= prime
        if n > 1:
            factors.append(n)
        return factors

    # Pre-compute primes up to 100
