    num = 3
    while len(primes) < 100:
        if is_prime(num):
            primes.append(num)
        num += 2

    # Find prime factors
    factors = prime_factors(n, primes)

    # Check for factors greater than 1000
    for prime in primes[100:]:
        if n % prime == 0:
            return prime

    # If no factor greater than 1000 is found, return None
    return None

