def second_smallest_even_indices(lst):
    # Input validation
    if not all(isinstance(i, (int, float)) for i in lst):
        raise TypeError("Input must be a list of numbers.")

    smallest_even = float('inf')
    second_smallest_even = float('inf')
    indices = []

    for i, num in enumerate(lst):
        if num % 2 == 0:  # Check if the number is even
            if num < smallest_even:
                second_smallest_even = smallest_even
                smallest_even = num
            elif smallest_even < num < second_smallest_even:
                second_smallest_even = num

        if num == smallest_even or num == second_smallest_even:
            indices.append(i)

    # If second_smallest_even remains infinity, there was no second smallest even number
    if second_smallest_even == float('inf'):
        return []

    return indices

