```python
class TrieNode:
    def __init__(self):
        self.children = {}  # Dictionary to store child nodes
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def _insert_helper(self, node, word, index):
        if index == len(word):
            node.is_end_of_word = True
            return

        char = word[index]
        if char not in node.children:
            node.children[char] = TrieNode()

        self._insert_helper(node.children[char], word, index + 1)

    def insert(self, word):
        if not isinstance(word, str) or not word:
            return  # Handle empty or non-string input

        self._insert_helper(self.root, word, 0)

    def _search_helper(self, node, word, index):
        if index == len(word):
            return node.is_end_of_word

        char = word[index]
        if char not in node.children:
            return False

        return self._search_helper(node.children[char], word, index + 1)

    def search(self, word):
        if not isinstance(word, str) or not word:
            return False  # Handle empty or non-string input

        return self._search_helper(self.root, word, 0)

    def _get_words_with_prefix(self, node, prefix, words):
        if node.is_end_of_word:
            words.append(prefix)

        for char, child_node in node.children.items():
            self._get_words_with_prefix(child_node, prefix + char, words)

    def startsWith(self, prefix):
        if not isinstance(prefix, str) or not prefix:
            return []  # Handle empty or non-string input

        words = []
        self._get_words_with_prefix(self.root, "", words)
        return words

# Example usage:
