            return False
        for i in range(2, num):
            if num % i == 0:
                return False
        return True

    prime_factors = []
    for potential_factor in range(2, n):
        if is_prime(potential_factor) and n % potential_factor == 0:
            prime_factors.append(potential_factor)

    # Incorrectly assumes sum of all factors (not distinct) is checked
    if len(prime_factors) != 3:
        return False

    # Incorrectly checks sum without ensuring distinctness
    if sum(prime_factors) <= n:
        return False

    return True

# Example usage:
