function swapElementsInNestedArray(arr, index1, index2) {
    // Validate indices
    if (!Array.isArray(arr) || index1 < 0 || index1 >= arr.length || index2 < 0 || index2 >= arr.length) {
        throw new Error("Invalid indices provided.");
    }

    // Deep copy the array to avoid modifying the original
    const newArr = JSON.parse(JSON.stringify(arr));

    // Function to safely traverse and swap elements
    function traverseAndSwap(current, path) {
        if (Array.isArray(current)) {
            for (let i = 0; i < current.length; i++) {
                const newPath = [...path, i];
                traverseAndSwap(current[i], newPath);
            }
        } else if (typeof current === 'object' && current !== null) {
            for (const key in current) {
                if (current.hasOwnProperty(key)) {
                    const newPath = [...path, key];
                    traverseAndSwap(current[key], newPath);
                }
            }
        } else {
            // Check if we have reached the target indices
            if (path.length === index1.length && path.every((p, i) => p === index1[i])) {
                newArr[path[0]] = current; // Mark the first element for swapping
            }
            if (path.length === index2.length && path.every((p, i) => p === index2[i])) {
                newArr[path[0]] = newArr[path[0]] || current; // Mark the second element for swapping
            }
        }
    }

    // Start traversal from the root level
    traverseAndSwap(newArr, []);

    // Swap marked elements at the top level
    const temp = newArr[index1[0]];
    newArr[index1[0]] = newArr[index2[0]];
    newArr[index2[0]] = temp;

    return newArr;
}

