import unittest

class TestTrie(unittest.TestCase):
    def setUp(self):
        self.trie = Trie()
        self.words = ["apple", "app", "banana", "ape", "bat", "ball"]
        for word in self.words:
            self.trie.insert(word)

    def test_insertion(self):
        self.trie.insert("apple")
        self.assertIn("apple", self.trie.search(""))
        self.assertEqual(self.trie.search("ap")[0], "apple")

    def test_deletion(self):
        self.trie.delete("apple")
        self.assertNotIn("apple", self.trie.search(""))
        self.trie.delete("nonexistent")  # Should not raise an error

    def test_search(self):
        self.assertEqual(self.trie.search(""), self.words)
        self.assertEqual(self.trie.search("a"), ["apple", "app", "ape"])
        self.assertEqual(self.trie.search("b"), ["banana", "bat"])
        self.assertEqual(self.trie.search("z"), [])

    def test_k_most_frequent(self):
        self.assertEqual(self.trie.k_most_frequent("", 2), ["apple", "banana"])
        self.assertEqual(self.trie.k_most_frequent("a", 2), ["app", "ape"])
        self.assertEqual(self.trie.k_most_frequent("b", 2), ["banana", "bat"])

if __name__ == '__main__':
    unittest.main()
```

### Explanation

- **TrieNode**: Each node stores child nodes, a flag indicating if it's the end of a word, and a frequency counter.
- **Trie**:
  - `insert`: Adds words, updating frequencies.
  - `delete`: Removes words, handling non-existent words gracefully.
  - `search`: Finds all words with a given prefix.
  - `k_most_frequent`: Efficiently retrieves the k most frequent words with a given prefix using a helper function to traverse the Trie.

