        x.height = 1 + max(self._height(x.left), self._height(x.right))

        return x

    def _rotate_left(self, x):
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        x.height = 1 + max(self._height(x.left), self._height(x.right))
        y.height = 1 + max(self._height(y.left), self._height(y.right))

        return y

    def _rebalance(self, node):
        balance_factor = self._balance_factor(node)

        # Left Left Case
        if balance_factor > 1 and self._balance_factor(node.left) >= 0:
            return self._rotate_right(node)

        # Right Right Case
        if balance_factor < -1 and self._balance_factor(node.right) <= 0:
            return self._rotate_left(node)

        # Left Right Case
        if balance_factor > 1 and self._balance_factor(node.left) < 0:
            node.left = self._rotate_left(node.left)
            return self._rotate_right(node)

        # Right Left Case
        if balance_factor < -1 and self._balance_factor(node.right) > 0:
            node.right = self._rotate_right(node.right)
            return self._rotate_left(node)

        return node  # Already balanced

    def insert(self, key):
        def _insert(node):
            if node is None:
                return TreeNode(key)

            if key < node.key:
                node.left = _insert(node.left)
            else:
                node.right = _insert(node.right)

            node.height = 1 + max(self._height(node.left), self._height(node.right))

            return self._rebalance(node)

        self.root = _insert(self.root)

    def delete(self, key):
        def _delete(node):
            if node is None:
                return None

            if key < node.key:
                node.left = _delete(node.left)
            elif key > node.key:
                node.right = _delete(node.right)
            else:
                if node.left is None:
                    return node.right
                elif node.right is None:
                    return node.left

                node.key = self._min_value_node(node.right).key
                node.right = _delete(node.right)

            if node is None:
                return node

            node.height = 1 + max(self._height(node.left), self._height(node.right))
            return self._rebalance(node)

        self.root = _delete(self.root)

    def search(self, key):
        node = self.root
        while node is not None:
            if key == node.key:
                return True
            elif key < node.key:
                node = node.left
            else:
                node = node.right
        return False

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current
```

### Sorting Algorithm: Stable Descending Sort by Length

To sort the strings in descending order of their lengths while maintaining stability, we can use a stable sorting algorithm like Merge Sort. Merge Sort has a time complexity of O(n log n) and is inherently stable.

#### Merge Sort Implementation
```python
def merge_sort(arr):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])

    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        if len(left[i]) >= len(right[j]) or (len(left[i]) == len(right[j]) and left[i] <= right[j]):
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return result
```

