import math
from typing import List

def sieve_of_eratosthenes(limit: int) -> List[bool]:
    """Generate a list of boolean values indicating prime numbers up to limit."""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return is_prime

def is_prime(n: int, primes: List[bool]) -> bool:
    """Check if a number is prime using precomputed primes up to its square root."""
    if n < 2:
        return False
    if n <= len(primes):
        return primes[n]
    for p in range(2, int(math.sqrt(n)) + 1):
        if n % p == 0:
            return False
    return True

def sum_of_primes(numbers: List[int]) -> int:
    """Sum all prime numbers in the given list."""
    if not all(isinstance(n, int) for n in numbers):
        raise ValueError("Input must be a list of integers.")

    if not numbers:
        return 0

    max_num = max(numbers)
    primes = sieve_of_eratosthenes(max_num)

    prime_sum = 0
    for num in numbers:
        if is_prime(num, primes):
            prime_sum += num

    return prime_sum

# Unit tests
import unittest

class TestSumOfPrimes(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(sum_of_primes([]), 0)

    def test_no_primes(self):
        self.assertEqual(sum_of_primes([4, 6, 8, 10]), 0)

    def test_single_prime(self):
        self.assertEqual(sum_of_primes([2]), 2)

    def test_multiple_primes(self):
        self.assertEqual(sum_of_primes([2, 3, 5, 7]), 17)

    def test_large_primes(self):
        self.assertEqual(sum_of_primes([1009, 1013, 1019]), 3041)

    def test_negative_numbers(self):
        self.assertEqual(sum_of_primes([-2, -3, -5, -7]), 0)

    def test_non_integer_input(self):
        with self.assertRaises(ValueError):
            sum_of_primes([2, 3.5, 5])

    def test_very_large_integers(self):
        # Test with very large primes to ensure no overflow
        self.assertEqual(sum_of_primes([10**10 - 1, 10**10 + 1]), 2)  # Only 2 is prime

if __name__ == '__main__':
    unittest.main()
