    # Add elements from list1
    for num in list1:
        if num >= 0 and not is_prime(num) and num % 2 == 0:
            merged_list.append(float(num))

    # Add elements from list2
    for num in list2:
        if num >= 0 and not is_prime(num) and num % 2 == 0:
            merged_list.append(float(num))

    # Sort the merged list
    merged_list.sort()

    # Add remaining odd numbers from list1
    for num in list1:
        if num >= 0 and not is_prime(num) and num % 2 != 0:
