```python
def distinct_permutations(s):
    # Check if input is a string
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    # Handle empty string case
    if len(s) == 0:
        return []

    # Use a set to store unique permutations
    unique_perms = set()

    # Helper function to generate permutations recursively
    def permute(current, remaining):
        if len(remaining) == 0:
            unique_perms.add(current)
        else:
            for i in range(len(remaining)):
                # Include the current character in the permutation
                permute(current + remaining[i], remaining[:i] + remaining[i+1:])

    # Start the permutation generation
    permute("", s)

    # Convert the set of permutations back to a list
    return list(unique_perms)
```

