```python
def find_palindromic_substrings(s):
    # Input validation
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    def is_palindrome(sub):
        return sub == sub[::-1]

    def has_only_repeating_chars(sub):
        return len(set(sub)) == 1

    palindromes = set()

    # Iterate over all possible substrings
    for i in range(len(s)):
        for j in range(i, len(s)):
            substring = s[i:j+1]
            if is_palindrome(substring) and not has_only_repeating_chars(substring):
                palindromes.add(substring)

    return palindromes

# Unit tests
import unittest

class TestPalindromicSubstrings(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(find_palindromic_substrings(""), set())

    def test_no_palindromes(self):
        self.assertEqual(find_palindromic_substrings("abc"), set())

    def test_all_repeating_chars(self):
        self.assertEqual(find_palindromic_substrings("aaa"), set())

    def test_mixed_palindromes(self):
        self.assertEqual(
            find_palindromic_substrings("abba"),
            {"a", "b", "bb", "abba"}
        )

    def test_odd_length_palindromes(self):
        self.assertEqual(
            find_palindromic_substrings("racecar"),
            {"r", "a", "c", "e", "aceca", "racecar"}
        )

    def test_even_length_palindromes(self):
        self.assertEqual(
            find_palindromic_substrings("level"),
            {"l", "e", "v", "el", "vel", "level"}
        )

    def test_mixed_palindromes_and_repeats(self):
        self.assertEqual(
            find_palindromic_substrings("aabbaa"),
            {"a", "b", "bb", "aa", "bbaa"}
        )

    def test_input_validation(self):
        with self.assertRaises(TypeError):
            find_palindromic_substrings(123)

if __name__ == '__main__':
    unittest.main()
```

