class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def calculate_area(self):
        return self.length * self.width

    def calculate_perimeter(self):
        return 2 * (self.length + self.width)

    def is_square(self):
        return self.length == self.width


def create_rectangle(length, width, perimeter):
    if (length + width) * 2 != perimeter:
        raise ValueError("Invalid perimeter value")
    return Rectangle(length, width)


