import re
from datetime import datetime

class Person:
    def __init__(self, name, age, hobbies, address):
        self.name = name
        self.age = self.validate_age(age)
        self.hobbies = self.validate_hobbies(hobbies)
        self.addresses = [self.validate_address(address)]
        self.max_hobbies = 10
        self.max_addresses = 5

    def validate_age(self, age):
        if isinstance(age, int) and age > 0:
            return age
        else:
            raise ValueError("Age must be a positive integer.")

    def validate_hobbies(self, hobbies):
        if isinstance(hobbies, list) and all(isinstance(hobby, str) for hobby in hobbies):
            return [hobby.strip() for hobby in hobbies if hobby.strip() and not any(char.isdigit() or not char.isalpha() for char in hobby)]
        else:
            raise ValueError("Hobbies must be a list of non-empty strings containing only alphabetic characters.")

    def validate_address(self, address):
        street, house_number, city, state, zip_code = address.split(',')
        street = street.strip()
        house_number = house_number.strip()
        city = city.strip()
        state = state.strip()
        zip_code = zip_code.strip()

        # Basic validation
        if not all(part for part in (street, house_number, city, state, zip_code)):
            raise ValueError("Address components cannot be empty.")

        # Street, house number, city, state validation
        if not (1 <= len(street) <= 50 and street.replace(" ", "").isalpha()):
            raise ValueError("Street name should contain only letters and spaces, max 50 characters.")
        if not house_number.isdigit() or len(house_number) > 3:
            raise ValueError("House number should be a 1-3 digit number.")
        if not (1 <= len(city) <= 50 and city.replace(" ", "").isalpha()):
            raise ValueError("City name should contain only letters and spaces, max 50 characters.")
        if not (1 <= len(state) <= 50 and state.replace(" ", "").isalpha()):
            raise ValueError("State name should contain only letters and spaces, max 50 characters.")

        # Zip code validation (US format example)
        if not re.match(r'^\d{5}$', zip_code):
            raise ValueError("Zip code should be a 5-digit number.")

        return {
            'street': street,
            'house_number': house_number,
            'city': city,
            'state': state,
            'zip_code': zip_code
        }

    def add_hobby(self, hobby):
        if len(self.hobbies) < self.max_hobbies:
            self.hobbies.append(hobby.strip())
        else:
            raise ValueError("Maximum number of hobbies reached.")

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def has_hobby(self, hobby):
        return hobby in self.hobbies

    def calculate_age_in_months(self):
        today = datetime.today()
        birth_date = datetime.strptime(f"{today.year - self.age}", "%Y-%m-%d")
        return (today.replace(month=1, day=1) - birth_date).days // 30

    def calculate_birth_year(self):
        return today.year - self.age

    def display_data(self):
        print(f"Name: {self.name.title()}")
        print(f"Age: {self.age} years")
        print("Hobbies:")
        for hobby in self.hobbies:
            print(f"- {hobby.title()}")
        print("Addresses:")
        for addr in self.addresses:
            print(f"Street: {addr['street']}, House Number: {addr['house_number']}, City: {addr['city']}, State: {addr['state']}, Zip Code: {addr['zip_code']}")

    def add_address(self, address):
        if len(self.addresses) < self.max_addresses:
            self.addresses.append(self.validate_address(address))
        else:
            raise ValueError("Maximum number of addresses reached.")

    def remove_address(self, address_id):
        if 0 <= address_id < len(self.addresses):
            del self.addresses[address_id]
        else:
            raise ValueError("Invalid address identifier.")

    def get_address(self, address_id):
        try:
            return self.addresses[address_id]
        except IndexError:
            raise ValueError("Invalid address identifier.")

# Example usage
person = Person("John Doe", 30, ["Reading", "Swimming"], "123 Main St, 456, Anytown, Anystate, 12345")
person.display_data()
person.add_hobby("Cycling")
person.remove_hobby("Swimming")
