def group_students(student_list):
    # Validate input
    if not isinstance(student_list, list):
        raise ValueError("Input must be a list.")

    for student in student_list:
        if not all(key in student for key in ["name", "major", "age", "GPA"]):
            raise ValueError("Each student object must contain 'name', 'major', 'age', and 'GPA' attributes.")

    # Group students by major
    grouped_students = {}
    for student in student_list:
        if student['GPA'] >= 3.0:
            major = student['major']
            if major not in grouped_students:
                grouped_students[major] = []
            grouped_students[major].append(student['name'])

    # Sort names within each major
    for major in grouped_students:
        grouped_students[major].sort()

    return grouped_students

# Unit tests
import unittest

class TestGroupStudents(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(group_students([]), {})

    def test_all_students_below_3_0_GPA(self):
        students = [
            {"name": "Alice", "major": "CS", "age": 20, "GPA": 2.9},
            {"name": "Bob", "major": "Math", "age": 21, "GPA": 2.8}
        ]
        self.assertEqual(group_students(students), {})

    def test_valid_input(self):
        students = [
            {"name": "Alice", "major": "CS", "age": 20, "GPA": 3.5},
            {"name": "Bob", "major": "Math", "age": 21, "GPA": 3.8},
            {"name": "Charlie", "major": "CS", "age": 22, "GPA": 3.2},
            {"name": "David", "major": "Physics", "age": 23, "GPA": 2.9}
        ]
        expected = {
            "CS": ["Alice", "Charlie"],
            "Math": ["Bob"]
        }
        self.assertEqual(group_students(students), expected)

    def test_students_with_extra_attributes(self):
        students = [
            {"name": "Alice", "major": "CS", "age": 20, "GPA": 3.5, "extra_attr": "value"},
            {"name": "Bob", "major": "Math", "age": 21, "GPA": 3.8, "extra_attr2": "value2"}
        ]
        expected = {
            "Math": ["Bob"]
        }
        self.assertEqual(group_students(students), expected)

    def test_students_missing_name(self):
        students = [
            {"major": "CS", "age": 20, "GPA": 3.5},
            {"major": "Math", "age": 21, "GPA": 3.8}
        ]
        with self.assertRaises(ValueError):
            group_students(students)

if __name__ == '__main__':
    unittest.main()
