from datetime import datetime, timedelta
from abc import ABC, abstractmethod

class LivingBeing:
    def __init__(self, name, species):
        self.name = name
        self.species = species

    @abstractmethod
    def speak(self):
        pass

    @abstractmethod
    def move(self):
