class Animal(LivingBeing):
    def __init__(self, name, species, creation_date):
        super().__init__(name, species)
        self.creation_date = creation_date
        self.age = self._calculate_age()

    def _calculate_age(self):
        today = datetime.today()
        age = today - self.creation_date
        return age.days // 365  # Simplified age calculation

    def eat(self, food):
        if not self._is_valid_food(food):
            raise ValueError(f"{self.species} cannot eat {food}")
        self.age += self._update_age_based_on_food(food)

