import re
from decimal import Decimal, InvalidOperation

def extract_digits(num_str):
    """
    Extract digits from a number string, handling various formats including:
    - Standard decimal numbers
    - Numbers in exponential notation (e.g., 1.23e-45)
    - Hexadecimal numbers (e.g., 0x1A2B3C)
    - Complex numbers (e.g., 3.14 + 2.71j)
    - Scientific notation (e.g., 3.14 x 10^5)

    Parameters:
    num_str (str): The string representation of the number.

    Returns:
    list: A list of digits extracted from the number.
    """

    # Validate input
    if not isinstance(num_str, str):
        raise ValueError("Input must be a string.")

    # Handle hexadecimal numbers
    if num_str.startswith('0x') or num_str.startswith('0X'):
        try:
            num = int(num_str, 16)
        except ValueError:
            raise ValueError("Invalid hexadecimal number.")
    else:
        # Handle complex numbers
        match = re.match(r'([-+]?\d+(\.\d+)?[+-](\d+(\.\d+)?)j)?', num_str)
        if match:
            real, imag = match.groups()
            try:
                real_num = Decimal(real or '0')
                imag_num = Decimal(imag or '0')
            except InvalidOperation:
                raise ValueError("Invalid complex number format.")
            num = complex(real_num, imag_num)
        else:
            # Handle decimal, exponential, and scientific notation
            try:
                num = Decimal(num_str)
            except InvalidOperation:
                match = re.match(r'([-+]?\d+(\.\d+)?[eE][-+]?\d+)', num_str)
                if match:
                    coeff, exp = match.groups()
                    try:
                        coeff_num = Decimal(coeff)
                        exp_num = int(exp)
                        num = coeff_num * (10 ** exp_num)
                    except (InvalidOperation, ValueError):
                        raise ValueError("Invalid scientific notation.")
                else:
                    raise ValueError("Invalid number format.")

    # Extract digits
    def _extract_digits(n):
        return [int(digit) for digit in str(abs(n))]

    if isinstance(num, complex):
        real_digits = _extract_digits(num.real)
        imag_digits = _extract_digits(num.imag)
        return real_digits, imag_digits
    else:
        return _extract_digits(num)

