```python
class City:
    def __init__(self, name, population, area, official_language):
        self.name = name
        self.population = population
        self.area = area
        self.official_language = official_language

    def __repr__(self):
        return f"{self.name} ({self.population} pop, {self.area} sq km, {self.official_language})"

class State:
    def __init__(self, name):
        self.name = name
        self.cities = []

    def add_city(self, city):
        self.cities.append(city)
        self.cities.sort(key=lambda x: x.population, reverse=True)

    def total_population(self):
        return sum(city.population for city in self.cities)

class IndiaStates:
    def __init__(self):
        self.states = {}

    def add_state(self, state_name):
        if state_name not in self.states:
            self.states[state_name] = State(state_name)

    def add_city_to_state(self, state_name, city_name, population, area, official_language):
        if state_name in self.states:
            self.states[state_name].add_city(City(city_name, population, area, official_language))
        else:
            raise ValueError(f"State '{state_name}' not found.")

    def get_state_cities(self, state_name):
        if state_name in self.states:
            return [city for city in self.states[state_name].cities]
        else:
            raise ValueError(f"State '{state_name}' not found.")

    def total_population_of_state(self, state_name):
        if state_name in self.states:
            return self.states[state_name].total_population()
        else:
            raise ValueError(f"State '{state_name}' not found.")

# Example usage:
india = IndiaStates()

