```python
import math
from decimal import Decimal, InvalidOperation

class AdvancedCalculator:
    def __init__(self):
        self.precision = 10

    def add(self, a, b):
        return round(Decimal(str(a)) + Decimal(str(b)), self.precision)

    def subtract(self, a, b):
        return round(Decimal(str(a)) - Decimal(str(b)), self.precision)

    def multiply(self, a, b):
        return round(Decimal(str(a)) * Decimal(str(b)), self.precision)

    def divide(self, a, b):
        if b == 0:
            raise ZeroDivisionError("Cannot divide by zero.")
        return round(Decimal(str(a)) / Decimal(str(b)), self.precision)

    def square_root(self, n):
        if n < 0:
            raise ValueError("Cannot calculate the square root of a negative number.")
        return round(Decimal(str(math.sqrt(n))), self.precision)

    def factorial(self, n):
        if n < 0:
            raise ValueError("Factorial is not defined for negative numbers.")
        result = 1
        for i in range(1, n + 1):
            try:
                result *= i
            except InvalidOperation:
                raise ValueError("Factorial calculation resulted in an overflow.")
        return result

    def power(self, base, exponent):
        return round(Decimal(str(math.pow(base, exponent))), self.precision)

