import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    def get_running_process(name):
        for proc in psutil.process_iter(['name']):
            if proc.info['name'] == name:
                return proc
        return None

    def ensure_process_terminated(proc):
        try:
            proc.terminate()
            proc.wait(timeout=5)  # Wait for up to 5 seconds for the process to terminate
        except (psutil.NoSuchProcess, psutil.TimeoutExpired):
            pass  # Process already terminated or timeout reached

    running_process = get_running_process(process_name)

    if running_process is None:
        print(f"Process not found. Starting {process_name}...")
        try:
            subprocess.Popen([process_name], shell=True)
            return "Process not found. Starting " + process_name + "."
        except Exception as e:
            return f"Error starting {process_name}: {str(e)}"

    else:
        print(f"Process found. Restarting {process_name}...")
        ensure_process_terminated(running_process)
        try:
            subprocess.Popen([process_name], shell=True)
            return "Process found. Restarting " + process_name + "."
        except Exception as e:
            return f"Error restarting {process_name}: {str(e)}"
