import numpy as np
from functools import reduce

def task_func(list_of_pairs):
    if not isinstance(list_of_pairs, list) or not all(isinstance(pair, tuple) for pair in list_of_pairs):
        raise TypeError("Input must be a list of tuples.")

    if not list_of_pairs:
        return np.array([1])

    second_values = np.array([pair[1] for pair in list_of_pairs])
    product = np.prod(second_values)

    return np.array([product])

# Unit tests
import unittest

class TestTaskFunc(unittest.TestCase):
    def test_empty_list(self):
        self.assertTrue(np.array_equal(task_func([]), np.array([1])))

    def test_single_tuple(self):
        self.assertTrue(np.array_equal(task_func([(1, 2)]), np.array([2])))

    def test_multiple_tuples(self):
        self.assertTrue(np.array_equal(task_func([(1, 2), (3, 4), (5, 6)]), np.array([120])))

    def test_zero_in_tuple(self):
        self.assertTrue(np.array_equal(task_func([(1, 0), (3, 4)]), np.array([0])))

    def test_negative_values(self):
        self.assertTrue(np.array_equal(task_func([(-1, 2), (-3, -4)]), np.array([-24])))

    def test_type_error(self):
