import os

def task_func(smtp_server, smtp_port, smtp_user, smtp_password, template_folder):
    app = Flask(__name__)

    # Validate input parameters
    if not all(isinstance(param, str) for param in [smtp_server, smtp_port, smtp_user, smtp_password, template_folder]):
        return jsonify({"error": "All parameters must be strings."})

    if not (1 <= smtp_port <= 65535):
        return jsonify({"error": "SMTP port must be an integer between 1 and 65535."})

    # Securely handle sensitive information
    if not smtp_user or not smtp_password:
        return jsonify({"error": "SMTP user and password are required."})

    # Configure Flask-Mail
    app.config.update(
        MAIL_SERVER=smtp_server,
        MAIL_PORT=smtp_port,
        MAIL_USE_TLS=True,  # Use TLS for secure connection
        MAIL_USE_SSL=False,  # Use TLS, not SSL
        MAIL_USERNAME=smtp_user,
        MAIL_PASSWORD=smtp_password,
        MAIL_DEBUG=False  # Disable debug mode for production
    )

    try:
        app.config['MAIL_TEMPLATES_FOLDER'] = template_folder
        mail = Mail(app)
    except Exception as e:
        return jsonify({"error": "Failed to configure Flask-Mail. Error: " + str(e)})

    @app.route('/send_test_email', methods=['POST'])
