import pandas as pd
import numpy as np
from random import choice

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]

def task_func(rows, columns):
    if rows < 1 or columns < 1:
        raise ValueError("Number of rows and columns must be at least 1.")

    np.random.seed(42)  # Seed for reproducibility

    def generate_random_data(data_type):
        if data_type is str:
            return ["".join(choice("abcdefghijklmnopqrstuvwxyz") for _ in range(5)) for _ in range(rows)]
        elif data_type is int:
            return np.random.randint(0, 10, size=rows).tolist()
        elif data_type is float:
            return [float(choice(range(10))) for _ in range(rows)]
        elif data_type is list:
            return [choice(range(10)) for _ in range(5) for _ in range(rows)]
        elif data_type is tuple:
            return [tuple(choice(range(10)) for _ in range(choice(range(1, 6)))) for _ in range(rows)]
        elif data_type is dict:
            return [{choice(range(10)): choice(range(10))} for _ in range(5) for _ in range(rows)]
        elif data_type is set:
            return {choice(range(10)) for _ in range(choice(range(1, 10))) for _ in range(rows)}
        else:
            raise ValueError(f"Unknown data type: {data_type}")

    columns_data = {}
    for col_name, data_type in zip(range(columns), np.random.choice(DATA_TYPES, columns, replace=False)):
        columns_data[f'col{col_name}'] = generate_random_data(data_type)

    df = pd.DataFrame(columns_data)
    return df
