import os
import json
from collections import Counter

def task_func(json_files_path='./json_files/', key='name'):
    if not os.path.isdir(json_files_path):
        return {"error": "The specified directory does not exist."}

    counts = Counter()

    for filename in os.listdir(json_files_path):
        if not filename.endswith('.json'):
            continue

        filepath = os.path.join(json_files_path, filename)
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                try:
                    data = json.load(file)
                    if isinstance(data, list):
                        for item in data:
                            if key in item:
                                counts[item[key]] += 1
                    elif isinstance(data, dict) and key in data:
                        counts[data[key]] += 1
                except json.JSONDecodeError:
                    return {f"Error decoding JSON in {filename}": "Invalid JSON format."}
        except Exception as e:
            return {f"Error accessing {filename}": str(e)}

    return dict(counts) if counts else {}
```

