    return wrapper

# SearchSignalsView
@api_view(['GET'])
@jwt_auth_required
@method_decorator(login_required, name='dispatch')
@csrf_exempt  # For testing purposes, disable CSRF protection
def SearchSignalsView(request):
    query = request.query_params.get('q', '')
    sort = request.query_params.get('sort', 'created_at')
    page = int(request.query_params.get('page', 1))
    per_page = int(request.query_params.get('per_page', 10))

    try:
        # Search for signals
        search_results = es.search(index='signals', body={
            "query": {
                "multi_match": {
                    "query": query,
                    "fields": ["name", "description"]
                }
            },
            "sort": [sort]
        })['hits']['hits']

        # Paginate results
        paginator = Paginator(search_results, per_page)
        page_objects = paginator.page(page)

        # Serialize results
        serialized_results = [SignalDocumentSerializer(signal).data for signal in page_objects]

        return Response(serialized_results)

    except Exception as e:
        return Response({"error": str(e)}, status=500)

