@api_view(['GET'])
@jwt_auth_required
@method_decorator(login_required, name='dispatch')
@csrf_exempt  # For testing purposes, disable CSRF protection
def SearchStatusMessagesView(request):
    query = request.query_params.get('q', '')
    state = request.query_params.get('state', None)
    active = request.query_params.get('active', None)
    page = int(request.query_params.get('page', 1))
    per_page = int(request.query_params.get('per_page', 10))

    try:
        # Filter and search for status messages
        search_results = StatusMessagesSearch.objects.filter(
            state=state, active=active
        ).values('id', 'message', 'created_at')

        # Paginate results
        paginator = Paginator(list(search_results), per_page)
        page_objects = paginator.page(page)

        # Serialize results
        serialized_results = [StatusMessagesSearchSerializer(item).data for item in page_objects]

        return Response(serialized_results)

    except Exception as e:
        return Response({"error": str(e)}, status=500)

