import unittest
from unittest.mock import patch, Mock
from datetime import datetime, timedelta

# Assuming the existence of a TenderStatusManager class with methods as described
class TenderStatusManager:
    def __init__(self):
        self.tender_statuses = {
            'below_threshold': {
                'no_bids': 'unsuccessful',
                'at_least_one_bid': 'qualification'
            },
            'open_ua': {
                'no_bids': 'unsuccessful',
                'at_least_one_bid': 'qualification'
            },
            'open_ua_defense': {
                'no_bids': 'unsuccessful',
                'at_least_one_bid': 'qualification'
            }
        }
        self.auction_periods = {
            'below_threshold': 7,
            'open_ua': 14,
            'open_ua_defense': 21
        }
        self.complaint_handling = {
            'below_threshold': lambda complaints: 'under_investigation',
            'open_ua': lambda complaints: 'under_investigation',
            'open_ua_defense': lambda complaints: 'under_investigation'
        }

    def transition_status(self, tender_type, bids, complaints):
        if tender_type not in self.tender_statuses:
            raise ValueError(f"Unknown tender type: {tender_type}")

        if bids == 0:
            return self.tender_statuses[tender_type]['no_bids']
        elif bids > 0:
            return self.tender_statuses[tender_type]['at_least_one_bid']

        # Handle complaints
        complaint_status = self.complaint_handling[tender_type](complaints)
        if complaint_status != 'under_investigation':
            return complaint_status

        # If no other conditions met, default to 'unsuccessful'
        return 'unsuccessful'

    def set_auction_period(self, tender_type):
        return self.auction_periods.get(tender_type, None)

    def log_transition(self, tender_id, new_status):
        print(f"Tender {tender_id} transitioned to {new_status} at {datetime.now()}")

# Unit tests
class TestTenderStatusManager(unittest.TestCase):

    def setUp(self):
        self.manager = TenderStatusManager()

    def test_below_threshold_no_bids(self):
        result = self.manager.transition_status('below_threshold', 0, 0)
        self.assertEqual(result, 'unsuccessful')

    def test_open_ua_one_bid(self):
        result = self.manager.transition_status('open_ua', 1, 0)
        self.assertEqual(result, 'qualification')

    def test_open_ua_defense_complaint(self):
        result = self.manager.transition_status('open_ua_defense', 0, 1)
        self.assertEqual(result, 'under_investigation')

    def test_unknown_tender_type(self):
        with self.assertRaises(ValueError):
            self.manager.transition_status('unknown_type', 0, 0)

    def test_auction_period(self):
        period = self.manager.set_auction_period('open_ua')
        self.assertEqual(period, 14)

    def test_logging(self):
        with patch('builtins.print') as mock_print:
            self.manager.log_transition('T123', 'qualification')
            mock_print.assert_called_with("Tender T123 transitioned to qualification at ...")

if __name__ == '__main__':
    unittest.main()
