import re
import math

class Runtime:
    def __init__(self):
        self.scope = {}  # Dictionary to hold variable and function definitions
        self.functions = {}  # Dictionary to hold user-defined functions

    def parse_expression(self, expr):
        """
        Parses and evaluates a mathematical expression.
        Supports variable lookups, function calls, and basic arithmetic operations.
        """
        def apply_operator(operators, values):
            operator = operators.pop()
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                values.append(left / right)

        def greater_precedence(op1, op2):
            precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
            return precedence[op1] > precedence[op2]

        expr = expr.replace(' ', '')  # Remove spaces for simplicity
        operators = []
        values = []
        i = 0
        while i < len(expr):
            if expr[i] == '(':
                operators.append(expr[i])
            elif expr[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Discard '('
            elif expr[i] in "0123456789.":
                j = i
                while j < len(expr) and (expr[j] in "0123456789." or expr[j] == '.'):
                    j += 1
                values.append(float(expr[i:j]))
                i = j - 1
            elif expr[i] in "+-*/":
                while (operators and operators[-1] in "*/-" and
                       greater_precedence(operators[-1], expr[i])):
                    apply_operator(operators, values)
                operators.append(expr[i])
            elif expr[i] == ',':
                i += 1
                continue
            elif expr[i] == ':':
                i += 1
                param = values.pop()
                values.append(param)
            elif expr[i].isalpha():
                var_name = expr[i]
                i += 1
                while i < len(expr) and expr[i].isalnum():
                    var_name += expr[i]
                    i += 1
                if var_name in self.scope:
                    values.append(self.scope[var_name])
                else:
                    raise NameError(f"Undefined variable: {var_name}")
            else:
                i += 1

        while operators:
            apply_operator(operators, values)
        return values[0]

    def define_variable(self, name, value):
        """Assigns a value to a variable."""
        self.scope[name] = value

    def define_function(self, name, params, body):
        """Defines a user-defined function."""
        self.functions[name] = (params, body)

    def call_function(self, name, args):
        """Evaluates a user-defined function with given arguments."""
        if name not in self.functions:
            raise NameError(f"Undefined function: {name}")
        params, body = self.functions[name]
        if len(args) != len(params):
            raise TypeError(f"Function {name} expects {len(params)} arguments, got {len(args)}")
        local_scope = self.scope.copy()
        for param, arg in zip(params, args):
            local_scope[param] = arg
        return self.parse_expression(body)

    def execute_command(self, command):
        """Executes a command from the user input."""
        parts = command.split()
        if parts[0] == 'define':
            if parts[1] == 'variable':
                if len(parts) != 3:
                    raise SyntaxError("Invalid variable definition syntax")
                self.define_variable(parts[2], None)  # Value is None for now
            elif parts[1] == 'function':
                if len(parts) < 4:
                    raise SyntaxError("Invalid function definition syntax")
                params = parts[3].split(',')
                body = ' '.join(parts[4:])
                self.define_function(parts[2], params, body)
            else:
                raise SyntaxError(f"Unknown command: {parts[0]}")
        elif parts[0] == 'assign':
            if len(parts) != 3:
                raise SyntaxError("Invalid assignment syntax")
            var, op, expr = parts[1:]
            value = self.parse_expression(expr)
            self.define_variable(var, value)
        elif parts[0] == 'call':
            if len(parts) < 3:
                raise SyntaxError("Invalid function call syntax")
            func_name = parts[1]
            args = [self.parse_expression(arg) for arg in parts[2:]]
            result = self.call_function(func_name, args)
            print(result)
        elif parts[0] == 'list':
            if parts[1] == 'vars':
                print("Variables:", ', '.join(self.scope.keys()))
            elif parts[1] == 'funcs':
                print("Functions:", ', '.join(self.functions.keys()))
            else:
                raise SyntaxError(f"Unknown list command: {parts[1]}")
        elif parts[0] == 'exit':
            return False
        else:
            try:
                result = self.parse_expression(' '.join(parts))
                print(result)
            except Exception as e:
                print(f"Error: {e}")

    def start_shell(self):
        """Starts an interactive shell for user commands."""
        print("Welcome to the Runtime Shell. Type 'exit()' to quit.")
        while True:
            command = input("> ")
            if not command:
                continue
            self.execute_command(command)
            if not self.execute_command('exit'):
                break

# Example usage:
