runtime.define_variable('pi', 3.14159)
runtime.define_function('square', 'x', 'x*x')
runtime.execute_command('assign x 5')
runtime.execute_command('assign y 3')
runtime.execute_command('call square x')  # Should print 25
runtime.execute_command('list vars')  # Should list variables
runtime.execute_command('list funcs')  # Should list functions
runtime.execute_command('exit')
