from typing import List, Dict, Any

# Mock action handlers for demonstration purposes
def add_to_queue_action(agent, queue):
    print(f"Agent {agent.id} added to queue {queue.id}")

def remove_from_queue_action(agent, queue):
    print(f"Agent {agent.id} removed from queue {queue.id}")

def update_penalty_action(agent, queue, new_penalty):
    print(f"Agent {agent.id} penalty updated to {new_penalty} in queue {queue.id}")

class Queue:
    def __init__(self, id: str):
        self.id = id

class Agent:
    def __init__(self, id: str, queues: Dict[str, int] = None, penalty: int = 0):
        self.id = id
        self.queues = queues if queues else {}
        self.penalty = penalty

class QueueDelta:
    def calculate(self, old_queues: List[Queue], new_queues: List[Queue]) -> Dict[str, List[Queue]]:
        if not all(isinstance(q, Queue) for q in old_queues + new_queues):
            raise ValueError("Both old_queues and new_queues must contain only Queue objects.")

        added = [q for q in new_queues if q not in old_queues]
        removed = [q for q in old_queues if q not in new_queues]
        penalty_updated = [q for q in new_queues if q in old_queues and self._penalties_changed(q, old_queues, new_queues)]

        return {
            'added': added,
            'removed': removed,
            'penalty_updated': penalty_updated
        }

    def _penalties_changed(self, queue: Queue, old_queues: List[Queue], new_queues: List[Queue]) -> bool:
        old_penalty = next((q.penalty for q in old_queues if q.id == queue.id), None)
        new_penalty = next((q.penalty for q in new_queues if q.id == queue.id), None)
        return old_penalty != new_penalty

class OnAgentUpdatedManager:
    def __init__(self, queue_delta: QueueDelta):
        self.queue_delta = queue_delta

    def on_agent_updated(self, agent: Agent):
        if not all(isinstance(q, Queue) for q in agent.queues.values()):
            raise ValueError("Agent queues must contain only Queue objects.")

        delta = self.queue_delta.calculate(list(agent.queues.keys()), list(agent.queues.keys()))

        for queue in delta['added']:
            add_to_queue_action(agent, queue)

        for queue in delta['removed']:
            remove_from_queue_action(agent, queue)

        for queue in delta['penalty_updated']:
            update_penalty_action(agent, queue, queue.penalty)

# Example usage
if __name__ == "__main__":
    # Initialize QueueDelta and OnAgentUpdatedManager
    queue_delta = QueueDelta()
    manager = OnAgentUpdatedManager(queue_delta)

    # Create some queues and agents
    queue1 = Queue("queue1")
    queue2 = Queue("queue2")
    agent1 = Agent("agent1", {queue1.id: 1, queue2.id: 2})
    agent2 = Agent("agent2", {queue1.id: 1})

    # Simulate agent updates
    manager.on_agent_updated(agent1)  # Should add agent1 to queues, update penalties
    manager.on_agent_updated(agent2)  # Should add agent2 to queue1
    manager.on_agent_updated(Agent("agent1", {}))  # Should remove agent1 from all queues

    # Test with invalid inputs to check error handling
    try:
        manager.on_agent_updated(Agent("agent3", {"invalid": "data"}))
    except ValueError as e:
        print(e)
