    # Check if the provided inputs are tuples containing two numeric values each.
    if not isinstance(point1, tuple) or not isinstance(point2, tuple):
        raise ValueError('Both inputs must be tuples.')
    if len(point1) != 2 or len(point2) != 2:
        raise ValueError('Both tuples must contain exactly two numeric values.')
    if not all(isinstance(i, (int, float)) for i in point1) or not all(isinstance(i, (int, float)) for i in point2):
        raise ValueError('Both tuples must contain numeric values.')

    # Calculate the Euclidean distance
    distance = ((point2[0] - point1[0]) ** 2 + (point2[1] - point1[1]) ** 2) ** 0.5
    return distance

# Test cases
print(euclidean_distance((1, 2), (4, 6)))  # Expected output: 5.0
print(euclidean_distance((0, 0), (3, 4)))  # Expected output: 5.0
print(euclidean_distance((-1, -1), (1, 1))) # Expected output: 4.242640687119285

# Testing invalid inputs
try:
    print(euclidean_distance((1, 2, 3), (4, 6)))  # Should raise ValueError
except ValueError as e:
    print(e)

try:
