```python
import pygame
import sys
from pygame.locals import *

# Constants
WIDTH, HEIGHT = 600, 600
CELL_SIZE = 10
FPS = 10

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)

pygame.init()
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Conway's Game of Life")
clock = pygame.time.Clock()

# Grid initialization
grid = [[0 for _ in range(WIDTH // CELL_SIZE)] for _ in range(HEIGHT // CELL_SIZE)]
grid_copy = [[0 for _ in range(WIDTH // CELL_SIZE)] for _ in range(HEIGHT // CELL_SIZE)]

def draw_grid():
    for y in range(HEIGHT // CELL_SIZE):
        for x in range(WIDTH // CELL_SIZE):
            color = WHITE if grid[y][x] else BLACK
            pygame.draw.rect(screen, color, (x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE))

def update_grid():
    global grid, grid_copy
    new_grid = [[0 for _ in range(WIDTH // CELL_SIZE)] for _ in range(HEIGHT // CELL_SIZE)]

    for y in range(HEIGHT // CELL_SIZE):
        for x in range(WIDTH // CELL_SIZE):
            live_neighbors = count_live_neighbors(x, y)
            if grid[y][x] == 1:
                if live_neighbors < 2 or live_neighbors > 3:
                    new_grid[y][x] = 0
                else:
                    new_grid[y][x] = 1
            elif live_neighbors == 3:
                new_grid[y][x] = 1

    grid_copy = new_grid.copy()

def count_live_neighbors(x, y):
    count = 0
    for i in range(-1, 2):
        for j in range(-1, 2):
            if (i == 0 and j == 0) or (x + i < 0 or x + i >= WIDTH // CELL_SIZE or y + j < 0 or y + j >= HEIGHT // CELL_SIZE):
                continue
            count += grid[y + j][x + i]
    return count

def toggle_cell(x, y):
    grid[y][x] = 1 - grid[y][x]

def main_menu():
    font = pygame.font.Font(None, 36)
    text_surface, rect = font.render("Configure Cells Manually", True, BLACK)
    text_surface2, rect2 = font.render("Start the Game", True, BLACK)

    while True:
        for event in pygame.event.get():
            if event.type == QUIT:
                pygame.quit()
                sys.exit()
            if event.type == KEYDOWN:
                if event.key == K_UP:
                    rect.top -= 5
                elif event.key == K_DOWN:
                    rect.top += 5
                elif event.key == K_RETURN:
                    return "Start the Game"
                elif event.key == K_BACKSPACE:
                    rect.top += 5 if rect.top > -rect.height else 0

        screen.fill((0, 0, 0))
        screen.blit(text_surface, (WIDTH // 2 - rect.width // 2, HEIGHT // 2 - rect.height // 2))
        screen.blit(text_surface2, (WIDTH // 2 - rect2.width // 2, HEIGHT // 2 + rect.height + 10))
        pygame.display.flip()
        clock.tick(FPS)

def main_loop():
    running = True
    configure = True

    while running:
        for event in pygame.event.get():
            if event.type == QUIT:
                running = False
            if event.type == MOUSEBUTTONDOWN:
                x, y = event.pos
                if 0 <= x // CELL_SIZE < WIDTH // CELL_SIZE and 0 <= y // CELL_SIZE < HEIGHT // CELL_SIZE:
                    toggle_cell(x // CELL_SIZE, y // CELL_SIZE)

        if configure:
            option = main_menu()
            if option == "Start the Game":
                configure = False

        update_grid()
        draw_grid()
        pygame.display.flip()
        clock.tick(FPS)

    pygame.quit()

if __name__ == "__main__":
    main_loop()
```

### Explanation:

1. **Initialization**: The Pygame library is initialized, and the screen is set up with a specified width and height. The grid is initialized as a 2D list of zeros, representing dead cells.

2. **Drawing the Grid**: The `draw_grid` function iterates over each cell in the grid and draws rectangles on the screen, using white for live cells and black for dead cells.

3. **Updating the Grid**: The `update_grid` function applies the rules of Conway's Game of Life to determine the state of each cell in the next generation. It uses a copy of the grid to avoid direct modification during the update process.

4. **Counting Live Neighbors**: The `count_live_neighbors` function counts the number of live neighbors for a given cell, considering the eight possible neighboring cells.

5. **Toggling Cells**: The `toggle_cell` function changes the state of a cell when clicked.

6. **Main Menu**: The `main_menu` function displays a simple menu allowing the user to choose between configuring cells manually and starting the game. The menu uses arrow keys for navigation and the Enter key for selection.

7. **Main Loop**: The `main_loop` function handles the game's main execution loop, including event handling for mouse clicks, updating the grid, and rendering the grid on the screen.

