class TestGameOfLife(unittest.TestCase):
    def test_count_live_neighbors(self):
        grid = [[0 for _ in range(5)] for _ in range(5)]
        grid[2][2] = 1  # Live cell at (2, 2)

        self.assertEqual(count_live_neighbors(2, 2), 1)  # Isolated live cell

        grid[1][2] = 1  # Live cell at (1, 2)
        grid[2][1] = 1  # Live cell at (2, 1)
        grid[2][3] = 1  # Live cell at (2, 3)

        self.assertEqual(count_live_neighbors(2, 2), 3)  # Surrounded by live neighbors

        grid[3][2] = 1  # Live cell at (3, 2)

        self.assertEqual(count_live_neighbors(2, 2), 4)  # Overpopulated

if __name__ == '__main__':
    unittest.main()
