    while True:
        try:
            value = int(input("Enter a positive integer (0 to finish): "))
            if value == 0:
                return None
            elif value > 0:
                return value
            else:
                print("Error: Please enter a positive integer.")
        except ValueError:
            print("Error: Invalid input. Please enter an integer.")

def calculate_average(numbers):
    if not numbers:  # Check if the list is empty
        return 0
    return sum(numbers) / len(numbers)

def main():
    numbers = []
    print("This program calculates the average of positive integers entered by the user.")
    print("Enter 0 to finish entering values.")

