        user_input = get_positive_integer_input()
        if user_input is None:  # User decided to finish by entering 0
            break
        elif not numbers or user_input == 0:  # First value can't be 0, subsequent 0 ends input
            print("Error: The first value cannot be 0. Please start over.")
            continue
        numbers.append(user_input)

    if numbers:
        average = calculate_average(numbers)
        print(f"The average of the entered values is: {average}")
    else:
        print("No positive integers were entered.")

if __name__ == "__main__":
    main()
