import json
import logging
from typing import Dict, Any
from aws_lambda_powertools import Logger, Tracer, Metrics

# Initialize AWS Lambda Powertools
logger = Logger()
tracer = Tracer()
metrics = Metrics()

def lambda_handler(event: Dict[str, Any], context: Any) -> Dict[str, Any]:
    """
    AWS Lambda function to process S3 object creation events.

    :param event: S3 event containing details about the created object.
    :param context: AWS Lambda context object.
    :return: A dictionary containing the S3 object's content and execution details.
    """
    try:
        # Extract S3 bucket name and object key from the event
        bucket_name = event['Records'][0]['s3']['bucket']['name']
        object_key = event['Records'][0]['s3']['object']['key']

        # Retrieve the S3 object content
        s3 = context.client('s3')
        response = s3.get_object(Bucket=bucket_name, Key=object_key)
        content = response['Body'].read().decode('utf-8', errors='ignore')

        # Log the content for debugging
        logger.info(f"S3 Object Content: {content}")

        # Record a custom metric
        metrics.increment('S3ObjectProcessed')

        # Prepare the response
        return {
            'content': content,
            'executionDetails': {
                'bucket': bucket_name,
                'key': object_key
            }
        }

    except Exception as e:
        # Log the exception and return an error message
        logger.error(f"Error processing S3 object: {e}")
        return {
            'error': str(e)
        }

# Unit tests (example using unittest framework)
