        result = lambda_handler(valid_event, None)
        self.assertIsInstance(result, dict)
        self.assertIn('content', result)
        self.assertIn('executionDetails', result)

    def test_invalid_s3_event(self):
        # Mock S3 event with invalid details (missing bucket name)
