            'Records': [
                {
                    's3': {
                        'object': {
                            'key': 'invalid-object.txt'
                        }
                    }
                }
            ]
        }
        # Call the lambda handler with the mock event
        result = lambda_handler(invalid_event, None)
        self.assertIsInstance(result, dict)
        self.assertIn('error', result)

if __name__ == '__main__':
    unittest.main()
