class MetadataFormatType:
    def __init__(self, prefix, schema, namespace):
        self.prefix = prefix
        self.schema = schema
        self.namespace = namespace

    def __repr__(self):
        return f"MetadataFormatType(prefix={self.prefix}, schema={self.schema}, namespace={self.namespace})"


class ListMetadataFormatsType:
    def __init__(self):
        self.formats = []

    def add_format(self, format_obj):
        if not isinstance(format_obj, MetadataFormatType):
            raise ValueError("Only instances of MetadataFormatType can be added.")
        if any(f.prefix == format_obj.prefix for f in self.formats):
            raise ValueError(f"Format with prefix {format_obj.prefix} already exists.")
        self.formats.append(format_obj)

    def get_formats(self):
        return self.formats

    def find_format(self, prefix):
        if prefix == "":
            return None
        return next((f for f in self.formats if f.prefix == prefix), None)


