import uuid

class FinancialTransactionProtocol:
    def __init__(self):
        self.transaction_id_counter = 0

    class Transaction:
        def __init__(self, sender, receiver, amount, currency):
            self.transaction_id = self._generate_transaction_id()
            self.sender = sender
            self.receiver = receiver
            self.amount = amount
            self.currency = currency

        @property
        def transaction_id(self):
            return self._transaction_id

        @transaction_id.setter
        def transaction_id(self, value):
            self._transaction_id = value

        @staticmethod
        def _generate_transaction_id():
            FinancialTransactionProtocol.transaction_id_counter += 1
            return str(uuid.uuid4())

        def is_valid(self):
            return self.amount >= 0

    class Confirmation:
        def __init__(self, transaction_id, success):
            self.transaction_id = transaction_id
            self.success = success

        @property
        def transaction_id(self):
            return self._transaction_id

        @transaction_id.setter
        def transaction_id(self, value):
            self._transaction_id = value

        def is_valid(self):
            return self.transaction_id and isinstance(self.success, bool)

    @staticmethod
    def create_transaction(sender, receiver, amount, currency):
        return FinancialTransactionProtocol.Transaction(sender, receiver, amount, currency)

    @staticmethod
    def create_confirmation(transaction_id, success):
        return FinancialTransactionProtocol.Confirmation(transaction_id, success)

    @staticmethod
    def check_message_validity(message):
        if isinstance(message, FinancialTransactionProtocol.Transaction):
            return message.is_valid() and message.transaction_id
        elif isinstance(message, FinancialTransactionProtocol.Confirmation):
            return message.is_valid() and message.transaction_id
        else:
            raise ValueError("Invalid message type")

# Example usage:

# Create a transaction
tx = FinancialTransactionProtocol.create_transaction("Alice", "Bob", 100, "USD")
print(f"Transaction ID: {tx.transaction_id}, Sender: {tx.sender}, Receiver: {tx.receiver}, Amount: {tx.amount}, Currency: {tx.currency}")

# Confirm the transaction
confirmation = FinancialTransactionProtocol.create_confirmation(tx.transaction_id, True)
print(f"Confirmation: ID={confirmation.transaction_id}, Success={confirmation.success}")

# Check validity
print(f"Transaction validity: {FinancialTransactionProtocol.check_message_validity(tx)}")
print(f"Confirmation validity: {FinancialTransactionProtocol.check_message_validity(confirmation)}")

# Attempt to create an invalid transaction
