import pytest
from unittest.mock import patch

class EnvCheck:
    @staticmethod
    def CmdCheck():
        """Check if 'cmd' is available in the system PATH."""
        try:
            subprocess.check_output(['cmd', '/c', 'echo'], stderr=subprocess.STDOUT)
            return True
        except subprocess.CalledProcessError:
            return False

    @staticmethod
    def AAPTCheck():
        """Check if 'aapt' is available and executable."""
        return os.path.isfile('aapt') and os.access('aapt', os.X_OK)

    @staticmethod
    def ZIPALIGNCheck():
        """Check if 'zipalign' is available and executable."""
        return os.path.isfile('zipalign') and os.access('zipalign', os.X_OK)

def pre_check():
    """Perform preliminary checks for Android build environment."""
    checks = [EnvCheck.CmdCheck, EnvCheck.AAPTCheck, EnvCheck.ZIPALIGNCheck]
    for check in checks:
        if not check():
            print(f"Error: {check.__name__} failed.")
            sys.exit(1)
    print("All checks passed.")

# Test cases using pytest and mock
@patch('builtins.print')
@patch('sys.exit')
def test_pre_check_success(mock_exit, mock_print):
    """Test pre_check() when all checks pass."""
    with patch('os.path.isfile', return_value=True), \
