import boto3
from botocore.exceptions import ClientError
from cryptography.fernet import Fernet

class DynamoDBSessionStore:
    def __init__(self, table_name, region_name='us-west-2'):
        self.table_name = table_name
        self.dynamodb = boto3.resource('dynamodb', region_name=region_name)
        self.table = self.dynamodb.Table(self.table_name)
        self.key_schema = ['SessionId']
        self.encryption_key = Fernet.generate_key()
        self.cipher_suite = Fernet(self.encryption_key)

    def _validate_session_key(self, session_key):
        if not isinstance(session_key, str) or not session_key:
            raise ValueError("Session key must be a non-empty string.")

    def _validate_session_data(self, session_data):
        if not isinstance(session_data, dict):
            raise ValueError("Session data must be a dictionary.")

    def load_session(self, session_key):
        self._validate_session_key(session_key)
        try:
            response = self.table.get_item(Key={'SessionId': session_key})
            if 'Item' in response:
                session_data = response['Item']
                # Decrypt session data
                for key, value in session_data.items():
                    if isinstance(value, str):
                        session_data[key] = self.cipher_suite.decrypt(value.encode()).decode()
                return session_data
            else:
                return None
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                return None
            else:
                raise

    def session_exists(self, session_key):
        self._validate_session_key(session_key)
        try:
            self.table.get_item(Key={'SessionId': session_key})
            return True
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                return False
            else:
                raise

    def create_session(self, session_key, session_data):
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        try:
            # Encrypt session data before storing
            encrypted_data = {k: self.cipher_suite.encrypt(v.encode()) for k, v in session_data.items()}
            self.table.put_item(Item=encrypted_data)
            return True
        except ClientError as e:
            if e.response['Error']['Code'] == 'ConditionalCheckFailedException':
                return False  # Session already exists
            else:
                raise

    def save_session(self, session_key, session_data):
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        try:
            # Encrypt session data before updating
            encrypted_data = {k: self.cipher_suite.encrypt(v.encode()) for k, v in session_data.items()}
            self.table.update_item(
                Key={'SessionId': session_key},
                UpdateExpression="set #{attr} = :val".format(attr=':session', val=encrypted_data),
                ExpressionAttributeValues={':session': encrypted_data, ':val': encrypted_data}
            )
            return True
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                return False  # Session does not exist
            else:
                raise

    def delete_session(self, session_key):
        self._validate_session_key(session_key)
        try:
            self.table.delete_item(Key={'SessionId': session_key})
            return True
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                return False  # Session does not exist
            else:
                raise

