import unittest

class TestDynamoDBSessionStore(unittest.TestCase):
    def setUp(self):
        self.session_store = DynamoDBSessionStore('test-sessions')

    def test_load_session(self):
        session_key = 'test_session'
        session_data = {'user_id': '123', 'last_active': '2023-04-01T12:00:00Z'}
        self.session_store.create_session(session_key, session_data)
        loaded_data = self.session_store.load_session(session_key)
        self.assertEqual(loaded_data, session_data)

    def test_session_exists(self):
        session_key = 'test_session'
        self.assertTrue(self.session_store.session_exists(session_key))
        non_existing_key = 'non_existing_session'
        self.assertFalse(self.session_store.session_exists(non_existing_key))

    def test_create_session(self):
        session_key = 'test_session'
        session_data = {'user_id': '123', 'last_active': '2023-04-01T12:00:00Z'}
        self.assertTrue(self.session_store.create_session(session_key, session_data))
        self.assertFalse(self.session_store.create_session(session_key, session_data))  # Should fail as session already exists

    def test_save_session(self):
        session_key = 'test_session'
        session_data = {'user_id': '123', 'last_active': '2023-04-01T12:00:00Z'}
        self.session_store.create_session(session_key, session_data)
        updated_data = {'user_id': '456', 'last_active': '2023-04-02T12:00:00Z'}
        self.assertTrue(self.session_store.save_session(session_key, updated_data))
        loaded_data = self.session_store.load_session(session_key)
        self.assertEqual(loaded_data, updated_data)

    def test_delete_session(self):
        session_key = 'test_session'
        self.session_store.create_session(session_key, {'user_id': '123'})
        self.assertTrue(self.session_store.delete_session(session_key))
        self.assertFalse(self.session_store.session_exists(session_key))

if __name__ == '__main__':
    unittest.main()
