        points = [Point(*p) for p in json_lane['points']]
        distance_points = [Point.from_distance(dp) for dp in json_lane['distancePoints']]
        intercept = json_lane['intercept']
        return Lane(lane_id, name, width, points, distance_points, intercept)

class Road:
