        self.road_id = road_id
        self.name = name
        self.road_type = road_type
        self.start_pos = start_pos
        self.length = length
        self.bearing = bearing
        self.connections = connections
        self.lanes = lanes

    @staticmethod
    def from_json(json_road):
        road_id = json_road['id']
        name = json_road['name']
        road_type = json_road['type']
        start_pos = json_road['startPos']
        length = json_road['length']
        bearing = json_road['bearing']
        connections = json_road['connections']
        lanes = [Lane.from_json(lane_json) for lane_json in json_road['lanes']]
        return Road(road_id, name, road_type, start_pos, length, bearing, connections, lanes)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    @staticmethod
    def from_distance(distance_point):
        return Point(distance_point['x'], distance_point['y'])

    def to_tuple(self):
        return (self.x, self.y)

class Map:
    def __init__(self, map_id, name, version, roads):
        self.map_id = map_id
        self.name = name
        self.version = version
        self.roads = roads

    @staticmethod
    def from_json(json_map):
        map_id = json_map['id']
        name = json_map['name']
        version = json_map['version']
        roads = [Road.from_json(road_json) for road_json in json_map['roads']]
        return Map(map_id, name, version, roads)

def read_and_parse_map_file(file_path):
    try:
        with open(file_path, 'r') as file:
            json_data = json.load(file)
            validate_map_structure(json_data)
            return Map.from_json(json_data)
    except FileNotFoundError:
        print(f"Error: The file at {file_path} was not found.")
    except json.JSONDecodeError as e:
        print(f"Error decoding JSON: {e}")
    except KeyError as e:
        print(f"Error: Missing required field in JSON data: {e}")

def validate_map_structure(json_data):
    # Basic validation checks, expand as needed
    if 'id' not in json_data or 'name' not in json_data or 'version' not in json_data or 'roads' not in json_data:
        raise KeyError("JSON data is missing required fields: 'id', 'name', 'version', or 'roads'")

def calculate_end_point(start_pos, length, bearing):
    # Convert bearing from degrees to radians
    bearing_rad = math.radians(bearing)
    # Calculate end point using basic trigonometry
    end_x = start_pos[0] + length * math.cos(bearing_rad)
    end_y = start_pos[1] + length * math.sin(bearing_rad)
    return (end_x, end_y)

