def find_diagonal_order(matrix):
    """
    Returns a list of integers representing the elements of the matrix in diagonal order.

    Parameters:
    matrix (list of list of int): A 2D list of integers.

    Returns:
    list of int: A list of integers in diagonal order.

    Raises:
    ValueError: If the input is not a 2D list of integers.
    """
    if not all(isinstance(i, list) and all(isinstance(j, int) for j in i) for i in matrix):
        raise ValueError("Input must be a 2D list of integers.")

    if not matrix:
        return []

    rows, cols = len(matrix), len(matrix[0])
    diagonal_order = []
    up_right = True

    def traverse_diagonal(r, c):
        nonlocal up_right
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        diagonal_order.append(matrix[r][c])
        if up_right:
            if c + 1 == cols:  # Reached the end of the column, move down
                r += 1
                c = -1  # Reset column index for the next diagonal
            else:
                c += 1
        else:
            if r + 1 == rows:  # Reached the end of the row, move up
                r = -1  # Reset row index for the next diagonal
            else:
                r += 1
        up_right = not up_right  # Alternate direction
        traverse_diagonal(r, c)

    for i in range(rows + cols - 1):
        if i < cols:  # First diagonal (up-right)
            r, c = 0, i
        elif i < rows:  # Subsequent diagonals
            r, c = i - cols + 1, cols - 1
        else:  # Last diagonal (down-left)
            r, c = rows - 1, cols - (i - rows + 1)
        traverse_diagonal(r, c)

    return diagonal_order

# Unit tests
