class TestDiagonalOrder(unittest.TestCase):
    def test_empty_matrix(self):
        self.assertEqual(find_diagonal_order([]), [])

    def test_single_row(self):
        self.assertEqual(find_diagonal_order([[1]]), [1])

    def test_single_column(self):
        self.assertEqual(find_diagonal_order([[1], [2], [3]]), [1, 2, 3])

    def test_simple_matrix(self):
        self.assertEqual(find_diagonal_order([[1, 2, 3], [4, 5, 6], [7, 8, 9]]), [1, 2, 4, 7, 5, 3, 6, 8, 9])

    def test_irregular_matrix(self):
        self.assertEqual(find_diagonal_order([[1, 2], [3, 4], [5]]), [1, 3, 5, 2, 4])

    def test_non_integer_values(self):
        with self.assertRaises(ValueError):
            find_diagonal_order([[1, 'a'], [4, 5]])

if __name__ == '__main__':
    unittest.main()
