# congress_utils.py

import datetime
import dateutil.parser
from typing import Union

class CongressError(Exception):
    """Base class for exceptions in this module."""
    def __init__(self, message, response=None, url=None):
        super().__init__(message)
        self.response = response
        self.url = url

class NotFound(CongressError):
    """Exception raised for errors in finding resources."""
    pass

def check_chamber(chamber: str) -> None:
    """Validate the chamber input."""
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError(f"Invalid chamber: {chamber}. Must be 'house', 'senate', or 'both'.")

def get_congress(year: int) -> int:
    """Calculate the Congress number for a given year."""
    if year < 1789:
        raise CongressError(f"Year {year} is before the first Congress in 1789.")
    return (year - 1789) // 2 + 1

def parse_date(date_str: str) -> Union[datetime.datetime, datetime.date]:
    """Parse a date string into a datetime object."""
    try:
        return dateutil.parser.parse(date_str)
    except (ValueError, TypeError):
        return datetime.datetime.strptime(date_str, "%Y-%m-%d").date()

def u(text: Union[str, bytes]) -> str:
    """Ensure text is a Unicode string with LF line endings."""
    if isinstance(text, bytes):
        text = text.decode('utf-8', 'replace')
    return text.replace('\r\n', '\n')

def get_offset(page: int) -> int:
    """Calculate the offset for pagination."""
    if page < 1:
        raise CongressError("Page number must be at least 1.")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.datetime.now().year)

# Test cases
if __name__ == "__main__":
    import doctest
    doctest.testmod()
```

### Explanation:

1. **CongressError and NotFound**: These are custom exception classes for handling API errors. `CongressError` is the base class, and `NotFound` is a subclass for not-found errors.

2. **check_chamber**: Ensures the input chamber is valid, raising a `TypeError` for invalid inputs.

3. **get_congress**: Computes the Congress number for a given year, raising a `CongressError` for years before 1789.

4. **parse_date**: Attempts to parse a date string using `dateutil.parser.parse`. If it fails, it falls back to `datetime.datetime.strptime` to ensure compatibility.

5. **u**: Converts text to Unicode and normalizes line endings.

6. **get_offset**: Computes the offset for pagination, raising a `CongressError` for invalid page numbers.

7. **CURRENT_CONGRESS**: A constant representing the current Congress number based on the current year.

