```python
import unittest
from typing import Dict, Any, Union

class MockTestRunner:
    def __init__(self):
        self.tests = []
        self.results = {
            'passed': [],
            'failed': [],
            'skipped': []
        }

    def add_test(self, test_name: str, test_type: str, expected_result: Any):
        """
        Add a test to the runner with its expected result.

        :param test_name: The name of the test.
        :param test_type: The type of test ('text', 'pixel', 'audio', 'virtual', 'reftest').
        :param expected_result: The expected result for the test (text, checksum, audio data, or reference file path).
        """
        if test_type not in ['text', 'pixel', 'audio', 'virtual', 'reftest']:
            raise ValueError(f"Invalid test type: {test_type}")

        self.tests.append({
            'name': test_name,
            'type': test_type,
            'expected': expected_result
        })

    def run_tests(self) -> Dict[str, list]:
        """
        Run all added tests and return a summary of the results.

        :return: A dictionary with lists of passed, failed, and skipped tests.
        """
        for test in self.tests:
            try:
                # Simulate test execution (in a real scenario, this would involve actual rendering and comparison)
                actual_result = self._simulate_test_execution(test)
                self._evaluate_test(test, actual_result)
            except Exception as e:
                self._mark_test_skipped(test, str(e))

        return self.results

    def _simulate_test_execution(self, test: dict) -> Any:
        """
        Simulate the execution of a test. In a real scenario, this would involve actual rendering and comparison.
        """
        # For demonstration, we'll just return a mock result based on test type
        if test['type'] == 'text':
            return test['expected']
        elif test['type'] == 'pixel':
            return f"PixelChecksum-{hash(test['expected'])}"
        elif test['type'] == 'audio':
            return f"AudioData-{hash(test['expected'])}"
        elif test['type'] == 'virtual':
            return "VirtualTestPassed"
        elif test['type'] == 'reftest':
            return f"RefTestPassed-{hash(test['expected'])}"
        else:
            raise ValueError(f"Unknown test type: {test['type']}")

    def _evaluate_test(self, test: dict, actual_result: Any):
        """
        Evaluate the test result and categorize it as passed, failed, or skipped.
        """
        if actual_result == test['expected']:
            self.results['passed'].append(test)
        else:
            self.results['failed'].append(test)

    def _mark_test_skipped(self, test: dict, reason: str):
        """
        Mark a test as skipped with a reason.
        """
        self.results['skipped'].append({**test, 'reason': reason})

    def get_detailed_results(self) -> list:
        """
        Return detailed results for each test.

        :return: A list of dictionaries, each containing test name, expected result, actual result, and pass/fail status.
        """
        detailed_results = []
        for test in self.tests:
            try:
                actual_result = self._simulate_test_execution(test)
                self._evaluate_test(test, actual_result)
                detailed_results.append({
                    'name': test['name'],
                    'expected': test['expected'],
                    'actual': actual_result,
                    'status': 'passed' if test in self.results['passed'] else 'failed' if test in self.results['failed'] else 'skipped'
                })
            except Exception as e:
                detailed_results.append({
                    'name': test['name'],
                    'expected': test['expected'],
                    'actual': None,
                    'status': 'skipped',
                    'reason': str(e)
                })
        return detailed_results

# Example usage:

class TestMockTestRunner(unittest.TestCase):
    def test_mock_runner(self):
        runner = MockTestRunner()

        # Adding tests
        runner.add_test('text_test', 'text', 'Expected Text')
        runner.add_test('pixel_test', 'pixel', 'PixelChecksum-abc123')
        runner.add_test('audio_test', 'audio', 'AudioData-def456')
        runner.add_test('virtual_test', 'virtual', 'VirtualTestPassed')
        runner.add_test('reftest_test', 'reftest', 'RefTestPassed-ghi789')

        # Running tests
        results = runner.run_tests()
        print("Summary Results:", results)

        # Detailed results
        detailed = runner.get_detailed_results()
        for result in detailed:
            print(result)

if __name__ == '__main__':
    unittest.main()
```

