from typing import List, Dict, Callable
from collections import defaultdict
import time

# Assuming VoIPController and related classes are defined as in the given snippet

class VoIPManager:
    def __init__(self):
        self.calls: Dict[int, VoIPController] = {}
        self.call_duration: Dict[int, float] = {}
        self.call_state_handlers: Dict[int, List[Callable[[CallState], None]]] = defaultdict(list)
        self.call_audio_frame_handlers: Dict[int, (Callable[[int], bytes], Callable[[bytes], None])] = defaultdict(lambda: (None, None))

    def start_call(self, call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool) -> bool:
        if not isinstance(call_id, int) or call_id <= 0:
            raise ValueError("Call ID must be a positive integer.")
        if not isinstance(endpoints, list) or not all(isinstance(ep, Endpoint) for ep in endpoints):
            raise ValueError("Endpoints must be a list of Endpoint objects.")
        if not isinstance(encryption_key, bytes) or len(encryption_key) != 32:  # Assuming 32 bytes for AES-256
            raise ValueError("Encryption key must be 32 bytes long.")
        if is_outgoing not in (True, False):
            raise ValueError("Direction must be True for outgoing calls and False for incoming calls.")

        call = VoIPController(call_id, endpoints, encryption_key, is_outgoing)
        self.calls[call_id] = call
        self.call_duration[call_id] = 0.0
        return True

    def end_call(self, call_id: int) -> None:
        if call_id not in self.calls:
            raise ValueError(f"No call with ID {call_id} exists.")

        call = self.calls[call_id]
        call.stop()
        del self.calls[call_id]
        del self.call_duration[call_id]
        # Clean up any resources associated with the call

    def get_call_duration(self, call_id: int) -> float:
        if call_id not in self.call_duration:
            raise ValueError(f"No call with ID {call_id} exists.")
        return self.call_duration[call_id]

    def set_call_state_changed_handler(self, call_id: int, handler: Callable[[CallState], None]) -> None:
        if call_id not in self.calls:
            raise ValueError(f"No call with ID {call_id} exists.")
        self.call_state_handlers[call_id].append(handler)

    def set_call_audio_frame_handlers(self, call_id: int, send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None]) -> None:
        if call_id not in self.calls:
            raise ValueError(f"No call with ID {call_id} exists.")
        self.call_audio_frame_handlers[call_id] = (send_handler, recv_handler)

    def _handle_call_state_change(self, call_id: int, state: CallState) -> None:
        if call_id in self.call_state_handlers:
            for handler in self.call_state_handlers[call_id]:
                handler(state)

    def _handle_audio_frame(self, call_id: int, frame: bytes) -> None:
        if call_id in self.call_audio_frame_handlers and self.call_audio_frame_handlers[call_id][1] is not None:
            self.call_audio_frame_handlers[call_id][1](frame)

    def _process_call(self, call_id: int) -> None:
        call = self.calls[call_id]
        while True:
            try:
                state = call.get_state()
                self._handle_call_state_change(call_id, state)

                if state == CallState.ACTIVE:
                    frame = call.receive_audio_frame()
                    if frame is not None:
                        self._handle_audio_frame(call_id, frame)

                time.sleep(0.01)  # Simulate processing time
            except Exception as e:
                print(f"Error processing call {call_id}: {e}")
                self.end_call(call_id)
                break

