```python

# app.py

from flask import Flask, render_template, request
from flask_socketio import SocketIO, emit
from threading import Lock

app = Flask(__name__)
socketio = SocketIO(app)

# Dictionary to store votes, protected by a lock for thread safety
vote_counts = {'yes': 0, 'no': 0, 'maybe': 0}
vote_lock = Lock()

def update_vote_counts(vote):
    """
    Updates the vote counts in a thread-safe manner.
    """
    with vote_lock:
        if vote in vote_counts:
            vote_counts[vote] += 1
        else:
            raise ValueError("Invalid vote: must be 'yes', 'no', or 'maybe'.")

@socketio.on('submit_vote')
def handle_submit_vote(data):
    """
    Handles the 'submit_vote' event, updates vote counts, and emits updated totals.
    """
    try:
        update_vote_counts(data['vote'])
        emit('update_vote_counts', vote_counts)
    except ValueError as e:
        emit('error', str(e), broadcast=True)

@app.route('/')
def index():
    """
    Serves the HTML page displaying the current vote totals.
    """
    return render_template('index.html', vote_counts=vote_counts)

if __name__ == '__main__':
    socketio.run(app, debug=True)

