        return self.data.get(package_name, None)

class PuppetIntegrityVerifier:
    def __init__(self, puppet_state_path: str):
        self.puppet_state_path = puppet_state_path
        self.verification_data = VerificationData()

    def load_puppet_state(self) -> Dict[str, Any]:
        if not os.path.exists(self.puppet_state_path):
            raise FileNotFoundError(f"Puppet state file not found at {self.puppet_state_path}")

        with open(self.puppet_state_path, 'r') as file:
