        puppet_state = self.load_puppet_state()
        if "File" in puppet_state and package_name in puppet_state["File"]:
            file_entry = puppet_state["File"][package_name]
            if "checksums" in file_entry and "md5" in file_entry["checksums"]:
                md5_checksum = file_entry["checksums"]["md5"]
                package_file_path = self.get_package_file_path(package_name)
                with open(package_file_path, "rb") as f:
                    file_md5 = hashlib.md5(f.read()).hexdigest()
                    if md5_checksum == file_md5:
                        print(f"Package {package_name} verified successfully.")
                    else:
                        print(f"Package {package_name} verification failed. Expected MD5: {md5_checksum}, Got: {file_md5}")
                self.verification_data.update(package_name, md5_checksum)
        else:
