from abc import ABC, abstractmethod

# Mixin classes
class GetHolidayMixin(ABC):
    @abstractmethod
    def get_holiday_by_id(self, holiday_id):
        pass

class DeleteHolidayMixin(ABC):
    @abstractmethod
    def delete_holiday_by_id(self, holiday_id):
        pass

class UpdateHolidayMixin(ABC):
    @abstractmethod
    def update_holiday_by_id(self, holiday_id, new_data):
        pass

# HolidayManager class inheriting from the mixins
class HolidayManager(GetHolidayMixin, DeleteHolidayMixin, UpdateHolidayMixin):
    def __init__(self):
        self.holidays = []

    def add_holiday(self, holiday):
        # Validate holiday dictionary
        if 'id' not in holiday or 'name' not in holiday or 'date' not in holiday:
            raise ValueError("Holiday must contain 'id', 'name', and 'date'.")
        self.holidays.append(holiday)

    def get_holiday_by_id(self, holiday_id):
        for holiday in self.holidays:
            if holiday['id'] == holiday_id:
                return holiday
        return f"No holiday found with id: {holiday_id}"

    def delete_holiday_by_id(self, holiday_id):
        self.holidays = [holiday for holiday in self.holidays if holiday['id'] != holiday_id]
        if not self.holidays:
            return "No holidays left to display."
        return f"Holiday with id {holiday_id} deleted."

    def update_holiday_by_id(self, holiday_id, new_data):
        if not {'name', 'date'}.intersection(new_data.keys()):
            raise ValueError("new_data must contain at least one of 'name' or 'date'.")

        for holiday in self.holidays:
            if holiday['id'] == holiday_id:
                holiday.update(new_data)
                return f"Holiday with id {holiday_id} updated."

        return f"No holiday found with id: {holiday_id}"

# Example usage
if __name__ == "__main__":
    holiday_manager = HolidayManager()

    # Adding holidays
    holiday_manager.add_holiday({'id': 1, 'name': 'New Year', 'date': '2023-01-01'})
    holiday_manager.add_holiday({'id': 2, 'name': 'Independence Day', 'date': '2023-07-04'})

    # Getting a holiday
    print(holiday_manager.get_holiday_by_id(1))

    # Updating a holiday
    print(holiday_manager.update_holiday_by_id(1, {'name': 'New Year Day', 'date': '2024-01-01'}))

    # Deleting a holiday
    print(holiday_manager.delete_holiday_by_id(2))

    # Attempting to get a non-existent holiday
    print(holiday_manager.get_holiday_by_id(3))
```

### Explanation:

1. **Mixin Classes**:
   - `GetHolidayMixin`: Provides the `get_holiday_by_id` method to retrieve a holiday by its ID.
   - `DeleteHolidayMixin`: Provides the `delete_holiday_by_id` method to remove a holiday by its ID.
   - `UpdateHolidayMixin`: Provides the `update_holiday_by_id` method to update a holiday by its ID, ensuring that `new_data` contains at least one of the keys `name` or `date`.

2. **HolidayManager Class**:
   - Inherits from `GetHolidayMixin`, `DeleteHolidayMixin`, and `UpdateHolidayMixin`.
   - The `__init__` method initializes an empty list `holidays`.
   - The `add_holiday` method validates the input dictionary to ensure it contains `id`, `name`, and `date`, then appends it to the `holidays` list.
   - The `get_holiday_by_id`, `delete_holiday_by_id`, and `update_holiday_by_id` methods are implemented to use the corresponding mixin methods.

3. **Example Usage**:
   - Demonstrates adding, retrieving, updating, and deleting holidays using the `HolidayManager` class.

This setup ensures that the `HolidayManager` class effectively manages holidays with the required functionalities provided by the mixins.

