import logging
from enum import Enum

# Setting up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DeviceState(Enum):
    """Enum for device states."""
    AVAILABLE = 1
    UNAVAILABLE = 2

class Device:
    """Base class for devices (switches and covers)."""
    def __init__(self, name):
        self.name = name
        self.state = DeviceState.AVAILABLE

    def toggle(self):
        """Toggle the device state."""
        if self.state == DeviceState.AVAILABLE:
            self.state = DeviceState.UNAVAILABLE
            logger.info(f"{self.name} toggled to UNAVAILABLE.")
        elif self.state == DeviceState.UNAVAILABLE:
            self.state = DeviceState.AVAILABLE
            logger.info(f"{self.name} toggled to AVAILABLE.")
        else:
            raise ValueError(f"Invalid state for {self.name}: {self.state}")

    def is_available(self):
        """Check if the device is available."""
        return self.state == DeviceState.AVAILABLE

class Switch(Device):
    """Switch device, can be turned on/off."""
    def __init__(self, name):
        super().__init__(name)
        self.is_on = False

    def turn_on(self):
        """Turn the switch on."""
        self.is_on = True
        logger.info(f"{self.name} turned ON.")

    def turn_off(self):
        """Turn the switch off."""
        self.is_on = False
        logger.info(f"{self.name} turned OFF.")

class Cover(Device):
    """Cover device, can be opened/closed."""
    def __init__(self, name):
        super().__init__(name)

    def open(self):
        """Open the cover."""
        if self.is_available():
            self.state = DeviceState.UNAVAILABLE
            logger.info(f"{self.name} opened.")
        else:
            raise ValueError(f"{self.name} is currently UNAVAILABLE.")

    def close(self):
        """Close the cover."""
        if self.is_available():
            self.state = DeviceState.AVAILABLE
            logger.info(f"{self.name} closed.")
        else:
            raise ValueError(f"{self.name} is currently UNAVAILABLE.")

class SmartHomeSystem:
    """Smart home system managing switches and covers."""
    def __init__(self):
        self.devices = {}

    def add_device(self, device):
        """Add a device to the system."""
        self.devices[device.name] = device

    def get_device(self, name):
        """Retrieve a device by name."""
        return self.devices.get(name)

    def toggle_device(self, name):
        """Toggle the availability state of a device."""
        device = self.get_device(name)
        if device:
            device.toggle()
        else:
            logger.warning(f"Device {name} not found.")

    def turn_on_switch(self, name):
        """Turn on a switch."""
        switch = self.get_device(name)
        if switch and switch.is_on is False:
            switch.turn_on()
        else:
            logger.warning(f"Switch {name} is either not a switch or already ON.")

    def turn_off_switch(self, name):
        """Turn off a switch."""
        switch = self.get_device(name)
        if switch and switch.is_on is True:
            switch.turn_off()
        else:
            logger.warning(f"Switch {name} is either not a switch or already OFF.")

    def open_cover(self, name):
        """Open a cover."""
        cover = self.get_device(name)
        if cover and cover.is_available():
            cover.open()
        else:
            logger.warning(f"Cover {name} is either not a cover or currently UNAVAILABLE.")

    def close_cover(self, name):
        """Close a cover."""
        cover = self.get_device(name)
        if cover and cover.is_available():
            cover.close()
        else:
            logger.warning(f"Cover {name} is either not a cover or currently UNAVAILABLE.")

    def get_device_status(self, name):
        """Get the current status of a device."""
        device = self.get_device(name)
        if device:
            status = f"Name: {device.name}, State: {device.state.name}, Switch On: {device.is_on if isinstance(device, Switch) else 'N/A'}"
            return status
        else:
            return f"Device {name} not found."

# Unit tests
import unittest

class TestSmartHomeSystem(unittest.TestCase):
    def setUp(self):
        self.system = SmartHomeSystem()
        self.switch = Switch("LivingRoomLight")
        self.cover = Cover("GarageDoor")
        self.system.add_device(self.switch)
        self.system.add_device(self.cover)

    def test_toggle_device(self):
        self.system.toggle_device("LivingRoomLight")
        self.assertFalse(self.system.get_device_status("LivingRoomLight").startswith("AVAILABLE"))
        self.system.toggle_device("LivingRoomLight")
        self.assertTrue(self.system.get_device_status("LivingRoomLight").startswith("AVAILABLE"))

    def test_turn_on_switch(self):
        self.system.turn_on_switch("LivingRoomLight")
        self.assertTrue(self.system.get_device_status("LivingRoomLight").endswith("ON"))
        self.system.turn_off_switch("LivingRoomLight")
        self.assertFalse(self.system.get_device_status("LivingRoomLight").endswith("ON"))

    def test_open_cover(self):
        self.system.open_cover("GarageDoor")
        self.assertFalse(self.system.get_device_status("GarageDoor").startswith("AVAILABLE"))
        with self.assertRaises(ValueError):
            self.system.open_cover("GarageDoor")  # Should raise an error as it's already open

    def test_close_cover(self):
        self.system.close_cover("GarageDoor")
        self.assertTrue(self.system.get_device_status("GarageDoor").startswith("AVAILABLE"))
        with self.assertRaises(ValueError):
            self.system.close_cover("GarageDoor")  # Should raise an error as it's already closed

    def test_get_device_status(self):
        self.assertEqual(self.system.get_device_status("LivingRoomLight"), "Name: LivingRoomLight, State: AVAILABLE, Switch On: False")
        self.assertEqual(self.system.get_device_status("GarageDoor"), "Name: GarageDoor, State: AVAILABLE, Switch On: N/A")

if __name__ == "__main__":
    unittest.main()
