        try:
            self.conn = sqlite3.connect(self.filepath)
            cursor = self.conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS NotDelivered (
                    containerId TEXT,
                    temperature INTEGER,
                    humidity INTEGER,
                    latitude REAL,
                    longitude REAL,
                    timestamp TEXT
                )
            ''')
            self.conn.commit()
        except sqlite3.Error as e:
            logging.error(f"Error creating table: {e}")
            raise

    def insert(self, data):
        if not self.conn:
            logging.error("Database connection not established.")
            return

        try:
            # Validate data structure
            required_keys = {'containerId', 'temperature', 'humidity', 'geo', 'timestamp'}
            if not set(data.keys()).issuperset(required_keys):
                raise ValueError("Missing required keys in data dictionary.")

            if not isinstance(data['containerId'], str):
                raise TypeError("containerId must be a string.")
            if not isinstance(data['temperature'], int):
                raise TypeError("temperature must be an integer.")
            if not isinstance(data['humidity'], int):
                raise TypeError("humidity must be an integer.")
            if not isinstance(data['geo'], dict):
                raise TypeError("geo must be a dictionary.")
            if 'latitude' not in data['geo'] or 'longitude' not in data['geo']:
                raise ValueError("geo dictionary must contain 'latitude' and 'longitude'.")
            if not isinstance(data['geo']['latitude'], (int, float)):
                raise TypeError("latitude must be a number.")
            if not isinstance(data['geo']['longitude'], (int, float)):
                raise TypeError("longitude must be a number.")
            if not isinstance(data['timestamp'], str):
                raise TypeError("timestamp must be a string.")

            cursor = self.conn.cursor()
            cursor.execute('''
                INSERT INTO NotDelivered (containerId, temperature, humidity, latitude, longitude, timestamp)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (
                data['containerId'], data['temperature'], data['humidity'], data['geo']['latitude'], data['geo']['longitude'], data['timestamp']
            ))
            self.conn.commit()
            logging.info("Data inserted successfully.")
        except sqlite3.Error as e:
            logging.error(f"Error inserting data: {e}")
        except ValueError as e:
            logging.error(f"Invalid data format: {e}")
        except TypeError as e:
            logging.error(f"Type mismatch in data: {e}")

    def close(self):
        if self.conn:
            self.conn.close()
            logging.info("Database connection closed.")

