class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        if not isinstance(title, str) or not isinstance(artist, str) or not isinstance(year, int) or not isinstance(genre, str):
            raise ValueError("Invalid data type. Title and Artist must be strings, Year must be an integer, Genre must be a string.")
        self.albums.append({
            'title': title,
            'artist': artist,
            'year': year,
            'genre': genre
        })
        print("Album added successfully.")

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        results = [album for album in self.albums if album.get(option) == value]
        return results


def main():
    album_service = AlbumService()
    while True:
        print("\nMusic Album Management System")
        print("1. Add a new album to the collection")
        print("2. Get all albums in the collection")
        print("3. Search for an album")
        print("4. Quit")

        choice = input("Enter your choice (1-4): ")

        if choice == '1':
            try:
                title = input("Enter album title: ")
                artist = input("Enter artist name: ")
                year = int(input("Enter release year: "))
                genre = input("Enter genre: ")
                album_service.add_record(title, artist, year, genre)
            except ValueError as e:
                print(f"Error: {e}")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

        elif choice == '2':
            albums = album_service.get_all_albums()
            if albums:
                for album in albums:
                    print(f"Title: {album['title']}, Artist: {album['artist']}, Year: {album['year']}, Genre: {album['genre']}")
            else:
                print("No albums found in the collection.")

        elif choice == '3':
            option = input("Enter search criteria (title, artist, year, genre): ").lower()
            while option not in ['title', 'artist', 'year', 'genre']:
                print("Invalid option. Please try again.")
                option = input("Enter search criteria (title, artist, year, genre): ").lower()

            value = input("Enter search value: ")
            try:
                results = album_service.search_by_option(option, value)
                if results:
                    for album in results:
                        print(f"Title: {album['title']}, Artist: {album['artist']}, Year: {album['year']}, Genre: {album['genre']}")
                else:
                    print("No matching albums found.")
            except Exception as e:
                print(f"An error occurred during search: {e}")

        elif choice == '4':
            print("Goodbye!")
            break
        else:
            print("Invalid choice. Please try again.")


if __name__ == "__main__":
    main()

