import ast
import fractions
from diofant import Symbol

# Helper function to check if a node should be ignored
def should_ignore(node):
    if isinstance(node, ast.Name):
        return node.id in dir(__builtins__) or (hasattr(node, 'ctx') and node.ctx == ast.Store)
    return False

# Integer Division Transformation
def transform_integer_division(node):
    if isinstance(node, ast.Div) and isinstance(node.right, ast.Num) and node.right.n % 1 == 0:
        node.right = ast.Num(n=fractions.Fraction(node.right.n, 1))
    return node

# Automatic Symbol Definition
def transform_symbols(node, namespace):
    if isinstance(node, ast.Name):
        if not should_ignore(node):
            if node.id not in namespace:
                namespace[node.id] = Symbol(node.id)
    return node

# Float Rationalization
def transform_float_to_fraction(node):
    if isinstance(node, ast.Num) and isinstance(node.n, float):
        node.n = fractions.Fraction(node.n)
    return node

# Unicode Identifiers Normalization
def normalize_unicode_identifiers(node):
    if isinstance(node, ast.Name):
        if not node.id.isascii():
            node.id = ''.join(c if c.isascii() else '_' for c in node.id)
    return node

# Main Transformation Function
def transform_code(code, namespace=None):
    if namespace is None:
        namespace = {}

    # Parse the code into an AST
    tree = ast.parse(code)

    # Traverse the AST and apply transformations
    for node in ast.walk(tree):
        if isinstance(node, ast.Div):
            node = transform_integer_division(node)
        if isinstance(node, ast.Name):
            node = transform_symbols(node, namespace)
        if isinstance(node, ast.Num):
            node = transform_float_to_fraction(node)
        if isinstance(node, ast.Name) and not should_ignore(node):
            node = normalize_unicode_identifiers(node)

    # Generate the transformed code from the modified AST
    transformed_code = compile(tree, '<string>', 'exec')
    exec(transformed_code, namespace)
    return ast.unparse(tree)

# Example usage
