from flask import Flask, request, jsonify, make_response
from flask_jwt_extended import (
    JWTManager, jwt_required, create_access_token,
    get_jwt_identity, get_raw_jwt
)
from werkzeug.security import generate_password_hash, check_password_hash
from functools import wraps

app = Flask(__name__)
app.config['JWT_SECRET_KEY'] = 'super-secret'  # Change this!
jwt = JWTManager(app)

# In-memory storage for users and tasks (replace with a database in production)
users = {}
tasks = {}

# User model
class UserModel:
    def __init__(self, email, password):
        self.email = email
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

# Task model
class TaskModel:
    def __init__(self, task_id, description, user_id):
        self.task_id = task_id
        self.description = description
        self.user_id = user_id

def create_task(description):
    user_id = get_jwt_identity()
    task_id = len(tasks) + 1
    tasks[task_id] = TaskModel(task_id, description, user_id)
    return tasks[task_id], 201

def get_user_tasks(user_id):
    return [task for task in tasks.values() if task.user_id == user_id], 200

def modify_task(task_id, description):
    user_id = get_jwt_identity()
    for task in tasks.values():
        if task.task_id == task_id and task.user_id == user_id:
            task.description = description
            return task, 200
    return None, 404

def delete_task(task_id):
    user_id = get_jwt_identity()
    for task_id, task in list(tasks.items()):
        if task.task_id == task_id and task.user_id == user_id:
            del tasks[task_id]
            return "", 204
    return None, 404

# Decorators for JWT protected routes
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = get_raw_jwt()
        if not token:
            return jsonify({"error": "Token is missing"}), 401
        try:
            current_user_id = get_jwt_identity()
        except:
            return jsonify({"error": "Token is invalid"}), 401
        return f(current_user_id, *args, **kwargs)
    return decorated

@app.route('/api/v2/register', methods=['POST'])
def register():
    if not request.json or not 'email' in request.json or not 'password' in request.json:
        return jsonify({"error": "Missing email or password"}), 400

    email = request.json['email']
    if email in users:
        return jsonify({"error": "Email already registered"}), 400

    password = request.json['password']
    user = UserModel(email, password)
    users[email] = user
    return jsonify({"message": "User registered successfully"}), 201

@app.route('/api/v2/login', methods=['POST'])
def login():
    if not request.json or not 'email' in request.json or not 'password' in request.json:
        return jsonify({"error": "Missing email or password"}), 400

    email = request.json['email']
    password = request.json['password']
    user = users.get(email)
    if not user or not user.check_password(password):
        return jsonify({"error": "Invalid email or password"}), 401

    access_token = create_access_token(identity=email)
    refresh_token = create_access_token(identity=email, fresh=True)
    return jsonify(access_token=access_token, refresh_token=refresh_token), 200

@app.route('/api/v2/refresh', methods=['POST'])
@token_required
def refresh():
    identity = get_jwt_identity()
    access_token = create_access_token(identity=identity)
    return jsonify(access_token=access_token), 200

@app.route('/api/v2/identity', methods=['GET'])
@token_required
def identity():
    return jsonify(identity=get_jwt_identity()), 200

@app.route('/api/v2/tasks', methods=['POST'])
@token_required
def create_task_endpoint():
    description = request.json.get('description')
    if not description:
        return jsonify({"error": "Description is required"}), 400

    task, status_code = create_task(description)
    return jsonify(task.__dict__), status_code

@app.route('/api/v2/tasks', methods=['GET'])
@token_required
def get_tasks_endpoint():
    tasks_list, status_code = get_user_tasks(get_jwt_identity())
    return jsonify(tasks_list), status_code

@app.route('/api/v2/tasks/<int:task_id>', methods=['PUT'])
@token_required
def update_task_endpoint(task_id):
    description = request.json.get('description')
    if not description:
        return jsonify({"error": "Description is required"}), 400

    task, status_code = modify_task(task_id, description)
    if not task:
        return jsonify({"error": "Task not found"}), 404
    return jsonify(task.__dict__), status_code

@app.route('/api/v2/tasks/<int:task_id>', methods=['DELETE'])
@token_required
def delete_task_endpoint(task_id):
    result, status_code = delete_task(task_id)
    if not result:
        return jsonify({"error": "Task not found"}), 404
    return "", status_code

if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation:

1. **User Registration (`/api/v2/register`)**:
   - Checks for required fields (`email`, `password`).
   - Ensures the email is not already registered.
   - Creates a new `UserModel` instance and stores it in memory.

2. **User Login (`/api/v2/login`)**:
   - Checks for required fields (`email`, `password`).
   - Verifies the password against the stored hash.
   - Generates and returns JWT access and refresh tokens.

3. **Token Refresh (`/api/v2/refresh`)**:
   - Requires a valid JWT token.
   - Generates a new access token.

4. **User Identity (`/api/v2/identity`)**:
   - Requires a valid JWT token.
   - Returns the identity (email) of the user.

5. **Task Operations**:
   - **Create Task (`/api/v2/tasks`)**:
     - Requires a valid JWT token.
     - Checks for a required `description` field.
     - Creates a new `TaskModel` instance and stores it in memory.
   - **Get Tasks (`/api/v2/tasks`)**:
     - Requires a valid JWT token.
     - Retrieves and returns all tasks associated with the authenticated user.
   - **Update Task (`/api/v2/tasks/<task_id>`)**:
     - Requires a valid JWT token.
     - Checks for a required `description` field.
     - Updates the task if it exists; returns 404 if not found.
   - **Delete Task (`/api/v2/tasks/<task_id>`)**:
     - Requires a valid JWT token.
     - Deletes the task if it exists; returns 404 if not found.

6. **Error Handling**:
   - Returns 400 for missing required fields.
   - Returns 404 for non-existent tasks.
   - Returns meaningful error messages for authentication failures.

### Note:
- This implementation uses in-memory storage for simplicity. In a production environment, replace this with a persistent database.
- The JWT secret key should be kept secure and not hardcoded in production.
- Additional error handling and input validation can be added as needed.

