class Model:
    def __init__(self, model_id):
        self.model_id = model_id

class FleetVehicleModel(Model):
    def __init__(self, model_id, program_id=None):
        super().__init__(model_id)
        self.program_id = program_id
        self.program = None

    def assign_program(self, program):
        if isinstance(program, VmsProgram):
            self.program = program
            self.program_id = program.program_id
        else:
            raise ValueError("Provided program is not an instance of VmsProgram")

    def get_program_details(self):
        if self.program:
            return {
                "name": self.program.name,
                "services": self.program.services,
                "inspections": self.program.inspections
            }
        else:
            return None

class VmsProgram:
    def __init__(self, name):
        self.name = name
        self.services = []
        self.inspections = []

    def add_service(self, service):
        self.services.append(service)

    def add_inspection(self, inspection):
        self.inspections.append(inspection)

# Unit tests
import unittest

class TestFleetVehicleModel(unittest.TestCase):
    def setUp(self):
        self.vehicle_model = FleetVehicleModel("V123")
        self.program = VmsProgram("Standard Maintenance")
        self.program.add_service("Oil Change")
        self.program.add_inspection("Tire Pressure Check")

    def test_assign_program(self):
        self.vehicle_model.assign_program(self.program)
        self.assertEqual(self.vehicle_model.program_id, self.program.program_id)  # Assuming program_id is set in VmsProgram

    def test_get_program_details(self):
        self.vehicle_model.assign_program(self.program)
        details = self.vehicle_model.get_program_details()
        self.assertEqual(details["name"], "Standard Maintenance")
        self.assertEqual(details["services"], ["Oil Change"])
        self.assertEqual(details["inspections"], ["Tire Pressure Check"])

class TestVmsProgram(unittest.TestCase):
    def setUp(self):
        self.program = VmsProgram("Basic Service")

    def test_add_service(self):
        self.program.add_service("Engine Oil Check")
        self.assertEqual(self.program.services, ["Engine Oil Check"])

    def test_add_inspection(self):
        self.program.add_inspection("Brake Pad Check")
        self.assertEqual(self.program.inspections, ["Brake Pad Check"])

if __name__ == '__main__':
    unittest.main()
