        for r in range(self.size):
            for c in range(self.size - 2):
                color = self.grid[r][c].color
                if color == self.grid[r][c+1].color == self.grid[r][c+2].color:
                    matches.append((r, c))
                    for i in range(3):
                        self.grid[r][c+i] = Gem(None)  # Clear matched gems
        return matches

    def cascade(self):
        for r in reversed(range(self.size)):
            for c in range(self.size - 1, -1, -1):
                if self.grid[r][c] is None:
                    for dr in range(r, 0, -1):
                        self.grid[dr][c] = self.grid[dr-1][c]
                        if self.grid[dr-1][c] is not None:
                            break
                    self.grid[r][c] = None

    def fill_grid(self):
        for c in range(self.size):
            for r in range(self.size - 1, -1, -1):
                if self.grid[r][c] is None:
                    for dr in range(r, 0, -1):
                        if self.grid[dr][c] is not None:
                            self.grid[r][c] = copy.copy(self.grid[dr-1][c])
                            break

    def is_game_over(self):
        # Check if all rows are filled with no empty spaces
        for row in self.grid:
            if None in row:
                return False
        return True

    def reshuffle(self):
        # Reshuffle logic (simplified for this example)
        self.grid = [[Gem(random.choice(['red', 'blue', 'green', 'yellow'])) for _ in range(self.size)] for _ in range(self.size)]
        self.update_score()  # Reshuffling might create new matches

    def display(self):
        for row in self.grid:
            print(" | ".join([gem.color if gem else '.' for gem in row]))
        print(f"Score: {self.score}")

# Game loop (simplified for demonstration)
def main():
    game = Grid()
    while True:
        game.display()
        # Simulate user input for swapping gems (for demonstration, random swap)
        row1, col1 = random.randint(0, 7), random.randint(0, 7)
        row2, col2 = random.randint(0, 7), random.randint(0, 7)
        if row1 != row2 or col1 != col2:  # Ensure adjacent swap
            game.swap(row1, col1, row2, col2)
            if game.is_game_over():
                game.reshuffle()
                game.score = 0  # Reset score on game over
        game.cascade()
        game.fill_grid()

if __name__ == "__main__":
    main()
