    def __init__(self, tweets: List[Tweet] = None):
        self.tweets = tweets if tweets else []

    @classmethod
    def from_dict(cls, tweet_dict: Dict[int, Dict[str, str]]) -> 'Tweets':
        tweets_instance = cls()
        for tweet_id, tweet_data in tweet_dict.items():
            try:
                created_at_str = tweet_data['created_at']
                created_at = datetime.datetime.fromisoformat(created_at_str)
                tweet = Tweet(tweet_id, tweet_data['text'], created_at, tweet_data['user_id'])
                tweets_instance.tweets.append(tweet)
            except KeyError as e:
                raise KeyError(f"Missing key in tweet data: {e}")
            except ValueError:
                raise ValueError(f"Invalid date format for tweet {tweet_id}")
        return tweets_instance

    def to_dict(self) -> Dict[int, Dict[str, str]]:
        tweet_dict = {}
        for tweet in self.tweets:
