class IoTCoreLoRaWAN:
    def __init__(self):
        self.devices = {}
        self.associations = {}
        self.profiles = {
            "default_profile": {"id": "default_profile", "name": "Default Profile"}
        }

    def _validate_device_profile(self, device_profile_id):
        if device_profile_id not in self.profiles:
            raise ValueError(f"Invalid device profile ID: {device_profile_id}")

    def create_wireless_device(self, name: str, device_profile_id: str) -> dict:
        self._validate_device_profile(device_profile_id)
        device_id = f"device_{len(self.devices) + 1}"
        self.devices[device_id] = {
            "name": name,
            "profile_id": device_profile_id,
            "associations": []
        }
        return self.devices[device_id]

    def delete_wireless_device(self, device_id: str) -> bool:
        if device_id not in self.devices:
            return False
        del self.devices[device_id]
        return True

    def associate_device_with_thing(self, device_id: str, thing_name: str) -> bool:
        if device_id not in self.devices:
            return False
        self.devices[device_id]["associations"].append(thing_name)
        self.associations[device_id] = thing_name
        return True

    def disassociate_device_from_thing(self, device_id: str) -> bool:
        if device_id not in self.devices:
            return False
        if device_id in self.associations:
            del self.associations[device_id]
            self.devices[device_id]["associations"] = []
        return True

    def get_wireless_device(self, device_id: str) -> dict:
        if device_id not in self.devices:
            raise ValueError(f"Device with ID {device_id} not found.")
        return self.devices[device_id]

