import torch
import torch.nn as nn
from torch.nn import functional as F

class GPP(nn.Module):
    def __init__(self, gpp_type, levels, pool_type='max_pool'):
        super(GPP, self).__init__()
        if gpp_type not in ['spp', 'tpp', 'gpp']:
            raise ValueError(f"Unknown gpp_type: {gpp_type}. Must be 'spp', 'tpp', or 'gpp'.")
        if pool_type not in ['max_pool', 'avg_pool']:
            raise ValueError(f"Unknown pool_type: {pool_type}. Must be 'max_pool' or 'avg_pool'.")

        self.gpp_type = gpp_type
        self.levels = levels
        self.pool_type = pool_type

    def forward(self, x, mask=None):
        if self.gpp_type == 'spp':
            return self._spatial_pyramid_pooling(x, self.levels, self.pool_type)
        elif self.gpp_type == 'tpp':
            return self._temporal_pyramid_pooling(x, self.levels, self.pool_type)
        elif self.gpp_type == 'gpp':
            return self._generic_pyramid_pooling(x, self.levels, self.pool_type)
        else:
            raise ValueError(f"Unknown gpp_type: {self.gpp_type}")

    def _spatial_pyramid_pooling(self, x, levels, pool_type):
        pooled_features = []
        for level in levels:
            pooled_features.append(F.adaptive_max_pool2d(x, (level, level)) if pool_type == 'max_pool' else F.adaptive_avg_pool2d(x, (level, level)))
        return torch.cat(pooled_features, dim=1)

    def _temporal_pyramid_pooling(self, x, levels, pool_type):
        # Assuming x has shape (batch_size, channels, height, width)
        # TPP would typically involve pooling over the temporal dimension (assumed to be the second dimension here for illustration)
        pooled_features = []
        for level in levels:
            pooled_features.append(F.adaptive_max_pool1d(x.transpose(1, 2).transpose(2, 3), (level)) if pool_type == 'max_pool' else F.adaptive_avg_pool1d(x.transpose(1, 2).transpose(2, 3), (level)))
        return torch.cat(pooled_features, dim=1).transpose(1, 2).transpose(2, 3)

    def _generic_pyramid_pooling(self, x, levels, pool_type):
        # levels is a tuple of two lists: [spatial_levels, temporal_levels]
        spatial_levels, temporal_levels = levels
        pooled_features = []

        for spatial_level in spatial_levels:
            spatial_pooled = self._spatial_pyramid_pooling(x, [spatial_level], pool_type)
            pooled_features.append(spatial_pooled)

        for temporal_level in temporal_levels:
            temporal_pooled = self._temporal_pyramid_pooling(x, [temporal_level], pool_type)
            pooled_features.append(temporal_pooled)

        return torch.cat(pooled_features, dim=1)

