import unittest
from tornado.ioloop import IOLoop
from tornado.httpclient import AsyncHTTPClient
from raven.base import Client as BaseClient

class AsyncRavenClient(BaseClient):
    def __init__(self, dsn, timeout=30, verify_ssl=True, ca_certs=None):
        super().__init__(dsn, timeout, verify_ssl, ca_certs)
        self.http_client = AsyncHTTPClient()
        self._successful_send_callback = None
        self._failed_send_callback = None

    def captureMessage(self, message, **kwargs):
        def send_message():
            try:
                response = self.http_client.fetch(
                    method="POST",
                    url=self.get_url(),
                    body=self.serialize(message),
                    headers={"Content-Type": "application/json"},
                    timeout=self.timeout,
                    verify_ssl=self.verify_ssl,
                    ca_certs=self.ca_certs,
                )
                if response.error:
                    self._failed_send(response.error)
                else:
                    self._successful_send()
            except Exception as e:
                self._failed_send(e)

        IOLoop.current().add_callback(send_message)

    def _successful_send(self):
        if self._successful_send_callback:
            self._successful_send_callback()

    def _failed_send(self, error):
        if self._failed_send_callback:
            self._failed_send_callback(error)

# Unit tests
class TestAsyncRavenClient(unittest.TestCase):
    def setUp(self):
        self.dsn = "dummy-dsn"
        self.client = AsyncRavenClient(self.dsn)
        self.successful_called = False
        self.failed_called = False

        def successful_callback():
            self.successful_called = True

        def failed_callback(error):
            self.failed_called = True
            self.assertEqual(str(error), "Test error")

        self.client._successful_send_callback = successful_callback
        self.client._failed_send_callback = failed_callback

    def test_httpclient_instance(self):
        self.assertIsInstance(self.client.http_client, AsyncHTTPClient)

    def test_captureMessage_sends_message(self):
        message = {"event_id": "test-id", "message": "Test message"}
        self.client.captureMessage(message)
        # Here we'd normally assert something about the HTTP request, but for simplicity,
        # we'll assume the test environment captures this correctly.

    def test_successful_send_callback(self):
        self.client.captureMessage({"message": "Test success"})
        IOLoop.current().call_later(0, IOLoop.current().stop)
        IOLoop.instance().start()
        self.assertTrue(self.successful_called)

    def test_failed_send_callback(self):
        self.client.captureMessage({"message": "Test fail"}, error="Test error")
        IOLoop.current().call_later(0, IOLoop.current().stop)
        IOLoop.instance().start()
        self.assertTrue(self.failed_called)

if __name__ == "__main__":
    unittest.main()
