import numpy as np

def get_positive_integer(prompt):
    while True:
        try:
            n = int(input(prompt))
            if n > 0:
                return n
            else:
                print("Please enter a positive integer.")
        except ValueError:
            print("Invalid input. Please enter a positive integer.")

def create_circular_adj_matrix(n):
    A = np.zeros((n, n), dtype=int)
    for i in range(n):
        A[i][i] = 3  # Set diagonal entries to 3
        if i < n - 1:  # For non-last row
            A[i][i + 1] = A[i + 1][i] = -1  # Set adjacent entries to -1
        else:  # For the last row, connect back to the first
            A[i][0] = A[0][i] = -1
    return A

def gaussian_elimination_determinant(A):
    n = len(A)
    det = 1
    for k in range(n):
        for i in range(k + 1, n):
            if A[i][k] != 0:
                factor = A[i][k] / A[k][k]
                A[i] -= factor * A[k]
                det *= factor
        if A[k][k] == 0:
            return 0  # Matrix is singular
    return det * np.prod(np.diag(A))

def main():
    n = get_positive_integer("Enter the number of vertices (n) in the cycle graph: ")
    A = create_circular_adj_matrix(n)
    determinant = gaussian_elimination_determinant(A)
    print(f"The determinant of the circular adjacency matrix is: {int(determinant)}")

if __name__ == "__main__":
    main()
