class Secure(object):
    def __init__(self, value, access_level=1):
        if not isinstance(value, (str, int, float, datetime)):
            raise ValueError("Unsupported data type. Only str, int, float, and datetime are supported.")
        self._value = value
        self._access_level = access_level
        self._encrypted_value = self.encrypt(value) if access_level >= 1 else value

    def encrypt(self, value):
