    def decrypt(self) -> Union[str, int, float, datetime]:
        if self._access_level >= 1:
            return cipher_suite.decrypt(self._encrypted_value).decode()
        return self._value

    def get_value(self, access_level: int) -> Union[str, int, float, datetime]:
        if access_level >= self._access_level:
            return self.decrypt()
        raise PermissionError("Insufficient access level to decrypt the value.")

class SecureString(Secure, str):
    def __new__(cls, value, access_level=1):
        return super().__new__(cls, Secure(value, access_level).get_value(access_level))

