from django.db import models
from django.core.validators import RegexValidator

# Custom PhoneField inheriting from CharField
class PhoneField(models.CharField):
    def __init__(self, *args, **kwargs):
        kwargs.setdefault('max_length', 30)
        kwargs.setdefault('verbose_name', 'Phone number')
        kwargs.setdefault('help_text', 'Phone number in international format')
        super().__init__(*args, **kwargs)

    def formfield(self, **kwargs):
        defaults = {'form_class': PhoneFormField}
        defaults.update(kwargs)
        return super().formfield(**defaults)

# Custom form field for PhoneField
class PhoneFormField(models.CharField):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.validator = RegexValidator(
            regex=r'^\+\d{1,3}\s\d{10,15}$',
            message="Phone number must be in the format +<CountryCode> <Number>",
        )

# Custom validator function
def validate_phone(value):
    if not value.startswith('+'):
        raise ValidationError("Phone number must start with a '+' sign.")

# Django model using the custom PhoneField
class Contact(models.Model):
    phone_number = PhoneField(validators=[validate_phone])

    class Meta:
        verbose_name = 'Contact'
        verbose_name_plural = 'Contacts'

    def clean(self):
        super().clean()
        if not self.phone_number:
            raise ValidationError("Phone number cannot be empty.")

# Example usage
if __name__ == "__main__":
    # Create a Contact instance
    contact = Contact(phone_number='+1 1234567890')
    contact.full_clean()  # This will pass as the phone number is valid
    print("Contact saved successfully.")

    # Attempt to save with an invalid phone number
    invalid_contact = Contact(phone_number='1234567890')
    try:
        invalid_contact.full_clean()
    except ValidationError as e:
        print(e)  # Output: Phone number must start with a '+' sign.

    # Attempt to save an empty phone number
    empty_contact = Contact(phone_number='')
    try:
        empty_contact.full_clean()
    except ValidationError as e:
        print(e)  # Output: Phone number cannot be empty.
