# models.py
from django.db import models

class Polygon(models.Model):
    """Model to store polygon information."""
    sides = models.PositiveIntegerField()
    side_lengths = models.JSONField()
    polygon_type = models.CharField(max_length=50, blank=True)

    def save(self, *args, **kwargs):
        """Determine polygon type on save."""
        self.polygon_type = self._get_polygon_type()
        super().save(*args, **kwargs)

    def _get_polygon_type(self):
        """Determine the type of polygon based on the number of sides."""
        sides = self.sides
        if sides == 3:
            return "Triangle"
        elif sides == 4:
            return "Quadrilateral"
        elif sides == 5:
            return "Pentagon"
        elif sides == 6:
            return "Hexagon"
        elif sides == 7:
            return "Heptagon"
        elif sides == 8:
            return "Octagon"
        else:
            return f"{sides}-gon"

# views.py
from rest_framework import status
from rest_framework.decorators import api_view
from rest_framework.response import Response
from rest_framework import generics
from .models import Polygon
from .serializers import PolygonSerializer

@api_view(['GET', 'POST'])
def polygon_detail(request, pk):
    """Retrieve or create a polygon by primary key."""
    try:
        polygon = Polygon.objects.get(pk=pk)
    except Polygon.DoesNotExist:
        return Response(status=status.HTTP_404_NOT_FOUND)

    if request.method == 'GET':
        serializer = PolygonSerializer(polygon)
        return Response(serializer.data)

    elif request.method == 'POST':
        serializer = PolygonSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class PolygonList(generics.ListAPIView):
    """List all polygons."""
    queryset = Polygon.objects.all()
    serializer_class = PolygonSerializer

class PolygonCreate(generics.CreateAPIView):
    """Create a new polygon."""
    queryset = Polygon.objects.all()
    serializer_class = PolygonSerializer

