class PolygonAPITestCase(TestCase):

    def setUp(self):
        self.client = APIClient()
        self.polygon_data = {
            'sides': 5,
            'side_lengths': [3, 4, 5, 6, 7]
        }

    def test_polygon_list(self):
        """Test listing all polygons."""
        response = self.client.get('/polygone/polygoneinfo/')
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertIsInstance(response.data, list)

    def test_polygon_detail_existing(self):
        """Test retrieving an existing polygon."""
        Polygon.objects.create(**self.polygon_data)
        response = self.client.get(f'/polygone/polygoneinfo/{Polygon.objects.first().pk}/')
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(response.data['sides'], 5)

    def test_polygon_detail_non_existing(self):
        """Test retrieving a non-existing polygon."""
        response = self.client.get('/polygone/polygoneinfo/999/')
        self.assertEqual(response.status_code, status.HTTP_404_NOT_FOUND)

    def test_polygon_create(self):
        """Test creating a new polygon."""
        response = self.client.post('/polygone/polygonecreate/', self.polygon_data)
        self.assertEqual(response.status_code, status.HTTP_201_CREATED)
        self.assertEqual(response.data['sides'], 5)

# Run tests
# python manage.py test
