class PluginManager:
    def __init__(self):
        self.plugins = {}

    def register_plugin(self, version, plugin_class):
        if version in self.plugins:
            raise ValueError(f"Plugin version {version} already registered.")
        self.plugins[version] = plugin_class()

    def get_plugin(self, version):
        if version not in self.plugins:
            raise KeyError(f"Plugin version {version} not found.")
        return self.plugins[version]

    def list_plugins(self):
        for version, plugin in self.plugins.items():
            print(f"Plugin Version: {version}")
            print(f"Capabilities: {plugin.capabilities()}")
            print("-" * 20)

